CREATE OR REPLACE FUNCTION beta_fantasy.actor(admin_required boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare u uuid; begin
 if (select deployment_mode from beta_fantasy.settings)='preview' then
  if coalesce(current_setting('docked.fantasy_production',true),'')<>'' then raise exception 'Production context forbidden in Preview'; end if;
  return beta_fantasy.preview_actor(admin_required);
 end if;
 u:=beta_fantasy.production_eligible();
 if not exists(select 1 from beta_fantasy.members where user_id=u and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Production membership required'; end if;
 if admin_required and (coalesce(auth.jwt()->>'aal','')<>'aal2' or not exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin'))) then raise exception 'Admin MFA required'; end if;
 return u;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.admin_name_team(p_user uuid, p_name text, p_previous text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform beta_fantasy.member_release_admin();
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,761));
 if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then raise exception 'Reason required';end if;
 perform set_config('docked.team_name_reason',p_reason,true);
 update beta_fantasy.team_names set name=p_name where user_id=p_user and name=p_previous;
 if not found then raise exception 'Established name changed; refresh before correcting it';end if;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.admin_prizes()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare answer jsonb;begin
 perform beta_fantasy.member_release_admin();
 answer:=beta_fantasy.admin_prizes_before_australian();
 return answer||jsonb_build_object(
  'templates',coalesce((select jsonb_agg(configuration order by version) from sports_feed.australian_prize_rules),'[]'),
  'rewardAudit',coalesce((select jsonb_agg(r.value) from credits_sandbox.state s cross join lateral jsonb_each(coalesce(s.document->'roundRewards','{}')) r where s.id),'[]'));
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.apply_weekly_prize_template(c beta_fantasy.competitions)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t beta_fantasy.weekly_prize_templates; product jsonb; items jsonb; created_id uuid;
begin
 if c.sport<>'nfl' or c.scored_at is not null or c.season !~ '^\d{4}$' then return;end if;
 select * into t from beta_fantasy.weekly_prize_templates where active and sport=c.sport and mode=c.rules->>'mode';
 if not found or (c.season::int,c.round)<(t.first_season,t.first_week) then return;end if;
 select document into strict product from credits_sandbox.pack_configuration where version=t.product_version;
 if product->>'sport'<>'nfl' or (product->>'cards')::int<>9 or product->>'type'<>(case when t.mode='OPEN' then 'PREMIUM' else 'STANDARD' end) then raise exception 'Invalid prize product reference';end if;
 select jsonb_agg(jsonb_build_object('from',n,'to',n,'description',q||' × '||(product->>'name')||' NFL','type','pack','amount',q,'productVersion',t.product_version) order by n) into items from (values(1,5),(2,3),(3,1))v(n,q);
 insert into beta_fantasy.prize_schedules(sport,mode,season,scope,week,competition_id,draft,published,effective_at)
 values(c.sport,t.mode,c.season,'weekly',c.round,c.id,items,items,clock_timestamp())
 on conflict(sport,mode,season,scope,week) do nothing returning id into created_id;
 if created_id is not null then
 insert into beta_private.audit_events(actor,action,subject,details) values('weekly-prize-template','prize_schedule_published',created_id::text,jsonb_build_object('template',to_jsonb(t),'items',items,'awardsIssued',false));
 end if;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.card_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare e beta_fantasy.editions; begin
 if tg_op='UPDATE' then
  if (to_jsonb(new)-'owner_id') is distinct from (to_jsonb(old)-'owner_id') then raise exception 'Card identity immutable'; end if;
 else
  select * into strict e from beta_fantasy.editions where id=new.edition_id for update;
  if e.status<>'launched' or e.launch_at>clock_timestamp() or new.serial<>e.issued+1 or new.serial>e.max_supply then raise exception 'Edition supply exhausted or invalid serial'; end if;
  update beta_fantasy.editions set issued=new.serial,locked_at=coalesce(locked_at,clock_timestamp()) where id=e.id;
 end if; return new; end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.entry_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cid uuid;c beta_fantasy.competitions;u uuid;cfg jsonb;begin
 cid:=case when tg_op='INSERT' then new.competition_id else old.competition_id end;
 select * into strict c from beta_fantasy.competitions where id=cid;
 if c.rules->>'lineup_version' is null then
 if c.locks_at<=clock_timestamp() or c.opens_at>clock_timestamp() or c.scored_at is not null then raise exception 'Lineup locked';end if;
 else
 perform pg_advisory_xact_lock(71820342);perform sports_feed.seven_lock_due();
 u:=case when tg_op='INSERT' then new.user_id else old.user_id end;
 if c.opens_at>clock_timestamp() or c.scored_at is not null then raise exception 'Lineup locked';end if;
 if (tg_op='DELETE' or (tg_op='INSERT' and not exists(select 1 from beta_fantasy.entries where competition_id=cid and user_id=u))) and c.locks_at<=clock_timestamp() then raise exception 'New entries and withdrawals closed';end if;
 if tg_op='UPDATE' and (new.user_id<>old.user_id or new.competition_id<>old.competition_id or new.id<>old.id) then raise exception 'Entry identity immutable';end if;
 if tg_op<>'DELETE' then
 select configuration into strict cfg from beta_fantasy.lineup_configurations where version=c.rules->>'lineup_version';
 if jsonb_array_length(new.snapshot)<>jsonb_array_length(cfg->'slots') or cardinality(new.cards)<>jsonb_array_length(cfg->'slots') or
 (select count(distinct s->>'player_id') from jsonb_array_elements(new.snapshot)s)<>jsonb_array_length(cfg->'slots') or
 (select count(distinct s->>'slot') from jsonb_array_elements(new.snapshot)s)<>jsonb_array_length(cfg->'slots') then raise exception 'Complete unique seven-slot snapshot required';end if;
 if exists(select 1 from beta_fantasy.slot_locks l where l.competition_id=cid and l.user_id=u and l.snapshot is distinct from (select s from jsonb_array_elements(new.snapshot)s where s->>'slot'=l.slot)) then raise exception 'Locked slot immutable';end if;
 end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.established_name_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare reason text;begin
 if tg_op='DELETE' then raise exception 'Established team names cannot be deleted';end if;
 perform beta_fantasy.member_release_admin();
 reason:=current_setting('docked.team_name_reason',true);
 if reason is null or length(btrim(reason)) not between 1 and 500 or new.user_id<>old.user_id then raise exception 'Audited administrator change required';end if;
 if new.name is null or new.name<>btrim(new.name) or length(new.name) not between 2 and 40 or new.name !~ '^[A-Za-z0-9][A-Za-z0-9 .''-]*$' then raise exception 'Invalid team name';end if;
 insert into beta_private.audit_events(actor,action,subject,details) values(auth.uid()::text,'team_name_admin_changed',old.user_id::text,jsonb_build_object('previous',old.name,'resulting',new.name,'reason',btrim(reason)));
 new.updated_at:=clock_timestamp();return new;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.initialize_production(project_ref text, terms text, privacy text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare starter uuid; reward uuid; comp uuid; scoring uuid; begin
 perform pg_advisory_xact_lock(71820342);
 if project_ref is null or terms is null or privacy is null or project_ref !~ '^[a-z]{20}$' or project_ref in('bckkllmndoxzpzdqrevb','dwdjeecjdkkiidoutnme') or terms !~ '^[a-zA-Z0-9][a-zA-Z0-9._-]{2,79}$' or privacy !~ '^[a-zA-Z0-9][a-zA-Z0-9._-]{2,79}$' or terms ~* '(draft|preview|fixture|pending|unapproved|placeholder)' or privacy ~* '(draft|preview|fixture|pending|unapproved|placeholder)' then raise exception 'Reviewed production identity and policy versions required'; end if;
 if (select deployment_mode from beta_fantasy.settings)<>'preview' or exists(select 1 from beta_fantasy.members) or exists(select 1 from beta_fantasy.cards) or exists(select 1 from beta_fantasy.journals) or exists(select 1 from beta_fantasy.entries) then raise exception 'Clean production Fantasy installation required'; end if;
 insert into beta_fantasy.pack_definitions(name,version,slots,pool,weights,guarantees,price,max_quantity,tradeable,ends_at)
 select 'Starter',2,'["GK","DEF","DEF","DEF","DEF","MID","MID","MID","MID","FWD","FWD"]',array_agg(id),'{"CORE":100}','{}',0,1000,false,clock_timestamp()+interval '100 years' from beta_fantasy.editions where tier='CORE' returning id into starter;
 insert into beta_fantasy.pack_definitions(name,slots,pool,weights,guarantees,price,max_quantity,tradeable,ends_at)
 select 'Daily reward', '["ANY"]',array_agg(id),'{"CORE":100}','{}',0,10000,false,clock_timestamp()+interval '100 years' from beta_fantasy.editions where tier='CORE' returning id into reward;
 insert into beta_fantasy.production_catalog values(true,starter,reward);
 insert into beta_fantasy.production_definitions values(starter,'starter'),(reward,'reward');
 insert into beta_fantasy.production_policy(daily_points,card_every,daily_card_limit) values(10,7,100);
 insert into beta_fantasy.scoring_rules(version,rules) select 'football-free-play-v1',rules from beta_fantasy.scoring_rules where version='football-demo-v1' returning id into scoring;
 insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id,prize) values('Free football league','football','2027',1,clock_timestamp()+interval '7 days','{"duplicates":false}',scoring,'No cash prize') returning id into comp;
 insert into beta_fantasy.production_rounds values(comp);
 update beta_fantasy.settings set deployment_mode='production',production_ref=project_ref,terms_version=terms,privacy_version=privacy,enabled=true;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.lineup(comp uuid, u uuid, ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare c beta_fantasy.competitions; s beta_fantasy.sports; item record; snapshot jsonb; begin
 select * into strict c from beta_fantasy.competitions where id=comp;
 select * into strict s from beta_fantasy.sports where id=c.sport;
 if (select count(*) from jsonb_object_keys(coalesce(c.rules->'positions',s.positions)))<>(select count(*) from jsonb_object_keys(s.positions)) or exists(select 1 from jsonb_each_text(coalesce(c.rules->'positions',s.positions)) f where not (s.positions ? f.key) or f.value::integer<0) or (select sum(value::integer) from jsonb_each_text(coalesce(c.rules->'positions',s.positions))) is distinct from s.team_size then raise exception 'Complete sport formation required'; end if;
 if cardinality(ids)<>s.team_size or (select count(distinct x) from unnest(ids) x)<>s.team_size then raise exception 'Invalid lineup size or duplicate card'; end if;
 if exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.packs pa on pa.id=pi.pack_id where pi.card_id=any(ids) and pa.opened_at is null) then raise exception 'Open pack before fielding cards'; end if;
 if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.id=any(ids) and a.owner_id=u and p.sport=c.sport and p.status not in('retired','delisted') and not exists(select 1 from beta_fantasy.listings l where l.card_id=a.id and l.state='active'))<>s.team_size then raise exception 'Ineligible, listed or unowned card'; end if;
 if coalesce((c.rules->>'duplicates')::boolean,false)=false and (select count(distinct e.player_id) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids))<>s.team_size then raise exception 'Duplicate player'; end if;
 for item in select key,value from jsonb_each_text(coalesce(c.rules->'positions',s.positions)) loop
  if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.id=any(ids) and p.position=item.key)<>item.value::integer then raise exception 'Invalid position formation'; end if;
 end loop;
 for item in select key,value from jsonb_each_text(coalesce(c.rules->'tier_max','{}')) loop
  if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids) and e.tier=item.key)>item.value::integer then raise exception 'Tier eligibility exceeded'; end if;
 end loop;
 if (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids) and e.kind='first_year')<coalesce((c.rules->>'first_year_min')::integer,0) or (select count(*) from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where a.id=any(ids) and e.tier='CORE')<coalesce((c.rules->>'core_min')::integer,0) then raise exception 'Minimum Core or First Year eligibility'; end if;
 select jsonb_agg(jsonb_build_object('card_id',a.id,'player_id',e.player_id,'tier',e.tier,'position',p.position,'season',e.season,'kind',e.kind) order by a.id) into snapshot from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players p on p.id=e.player_id where a.id=any(ids);
 return snapshot; end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.member_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 perform pg_advisory_xact_lock(71820342);
 if (select deployment_mode from beta_fantasy.settings)='preview' and new.revoked_at is null and new.expires_at>clock_timestamp() and (select count(*) from beta_fantasy.members where user_id<>new.user_id and revoked_at is null and expires_at>clock_timestamp())>=3 then raise exception 'Preview limited to three members'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.mint(eid uuid, u uuid, tradeable boolean, reason text, ref uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare c uuid; e beta_fantasy.editions; begin
 select * into strict e from beta_fantasy.editions where id=eid for update;
 insert into beta_fantasy.cards(edition_id,serial,owner_id,tradeable) values(eid,e.issued+1,u,tradeable) returning id into c;
 insert into beta_fantasy.ownership_events(card_id,to_user,reason,reference,prospect_rank) values(c,u,reason,ref,e.prospect_rank);
 return c; end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.money(reason text, ref uuid, accounts text[], amounts bigint[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare j uuid; i integer; begin
 if cardinality(accounts)<>cardinality(amounts) or (select sum(x) from unnest(amounts) x)<>0 then raise exception 'Unbalanced journal'; end if;
 insert into beta_fantasy.journals(reason,reference) values(reason,ref) returning id into j;
 for i in 1..cardinality(accounts) loop if amounts[i]<>0 then insert into beta_fantasy.ledger(journal_id,account,amount) values(j,accounts[i],amounts[i]); end if; end loop;
 if exists(select 1 from beta_fantasy.ledger where account not like 'system:%' group by account having sum(amount)<0) then raise exception 'Insufficient credits'; end if;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.my_nfl_pack_receipt()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; answer jsonb; begin
 u:=beta_fantasy.production_eligible();
 if u is null or not beta_private.active_member_session() or not exists(select 1 from sports_feed.nfl_control where enabled) then raise exception 'Active NFL member required';end if;
 select jsonb_build_object('id',a.user_id::text||':nfl-starter','name','NFL starter pack','opened_at',a.created_at,'cards',(
  select jsonb_agg(jsonb_build_object(
   'id',c.id,'edition_id',e.id,'serial',c.serial,'name',p.name,'position',p.position,
   'tier',e.tier,'season',e.season,'kind',e.kind,'max_supply',e.max_supply,
   'player_id',p.id,'team',np.current_team,'edition_team',np.edition_team,
   'colour',p.colour,'shirt',p.shirt,'status',p.status,'sport',p.sport,'tradeable',c.tradeable
  ) order by x.n)
  from unnest(a.card_ids) with ordinality x(id,n)
  join beta_fantasy.cards c on c.id=x.id join beta_fantasy.editions e on e.id=c.edition_id
  join beta_fantasy.players p on p.id=e.player_id join sports_feed.nfl_players np on np.player_id=p.id
 )) into answer from sports_feed.nfl_allocations a where a.user_id=u;
 return answer;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.my_team_name()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare u uuid;begin
 u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() or not exists(select 1 from sports_feed.nfl_control where enabled) then raise exception 'Active NFL member required';end if;
 return (select name from beta_fantasy.team_names where user_id=u);
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.name_team(p_name text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;prior beta_fantasy.requests;answer jsonb;payload jsonb;begin
 if current_setting('docked.public_gameplay',true)='enabled' then u:=public_gameplay.identity();else u:=beta_fantasy.production_eligible();end if;
 if current_setting('docked.public_gameplay',true) is distinct from 'enabled' and (u is null or not beta_private.active_member_session() or not exists(select 1 from sports_feed.nfl_control where enabled)) then raise exception 'Active NFL member required';end if;
 if p_request is null or p_name is null or p_name<>btrim(p_name) or length(p_name) not between 2 and 40 or p_name !~ '^[A-Za-z0-9][A-Za-z0-9 .''-]*$' then raise exception 'Use 2 to 40 letters, numbers, spaces or simple punctuation';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,761));
 payload:=jsonb_build_object('name',p_name);
 select * into prior from beta_fantasy.requests where user_id=u and request_id=p_request;
 if found then if prior.action<>'name_team' or prior.payload<>payload then raise exception 'Request ID reused';end if;return prior.result;end if;
 if exists(select 1 from beta_fantasy.team_names where user_id=u) then raise exception 'Your team name is permanent. Contact an administrator for a correction.';end if;
 insert into beta_fantasy.members(user_id,expires_at) values(u,'infinity') on conflict do nothing;
 insert into beta_fantasy.team_names(user_id,name) values(u,p_name);
 answer:=jsonb_build_object('saved',true,'name',p_name);
 insert into beta_private.audit_events(actor,action,subject,details) values(u::text,'beta_team_named',u::text,jsonb_build_object('previous',null,'resulting',p_name,'request',p_request));
 insert into beta_fantasy.requests values(u,p_request,'name_team',payload,answer);
 return answer;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.prepare_pack(pack_id uuid, u uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare pack beta_fantasy.packs; d beta_fantasy.pack_definitions; chosen beta_fantasy.editions; i integer; item record; selected_tier text; slot_position text; weights double precision; draw double precision; cid uuid;
begin
 select * into strict pack from beta_fantasy.packs where id=pack_id and user_id=u;
 select * into strict d from beta_fantasy.pack_definitions where id=pack.definition_id;
   -- Charge only when issuance succeeds. An exhausted pool cannot strand paid credits.
   if d.price>0 then perform beta_fantasy.money('pack',pack.id,array[u::text,'system:pack'],array[-d.price,d.price]); end if;
   for i in 0..jsonb_array_length(d.slots)-1 loop
    slot_position:=d.slots->>i;
    -- Guarantees occupy configured leading slots; other slots use explicit tier weights.
    selected_tier:=d.guarantees->>i::text;
    if selected_tier is null then
     select sum(value::double precision) into weights from jsonb_each_text(d.weights);
     if weights is null or weights<=0 or exists(select 1 from jsonb_each_text(d.weights) where value::double precision<0) then raise exception 'Invalid pack weights'; end if;
     draw:=random()*weights;
     for item in select key,value::double precision as weight from jsonb_each_text(d.weights) order by key loop
      draw:=draw-item.weight; if draw<0 then selected_tier:=item.key; exit; end if;
     end loop;
    end if;
    select a.* into chosen from beta_fantasy.editions a join beta_fantasy.players b on b.id=a.player_id where a.id=any(d.pool) and a.tier=selected_tier and a.status='launched' and a.launch_at<=clock_timestamp() and a.issued<a.max_supply and b.status not in('retired','delisted') and (slot_position='ANY' or b.position=slot_position) and (d.name<>'Starter' or not exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.cards ci on ci.id=pi.card_id join beta_fantasy.editions ei on ei.id=ci.edition_id where pi.pack_id=pack.id and ei.player_id=a.player_id)) order by random() limit 1;
    if not found then raise exception 'Configured pool exhausted; no reroll or debit'; end if;
    cid:=beta_fantasy.mint(chosen.id,u,d.tradeable,case when d.name='Starter' then 'starter' else 'pack' end,pack.id);
    insert into beta_fantasy.pack_items values(pack.id,i,cid);
   end loop;

end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.preview_actor(admin_required boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare u uuid:=auth.uid(); begin
 if current_setting('docked.fantasy_preview',true) is distinct from 'test-credits-only' or not (select enabled from beta_fantasy.settings) then raise exception 'Fantasy Preview disabled'; end if;
 perform 1 from beta_fantasy.members where user_id=u for share;
 perform 1 from beta_public.profiles where id=u for share;
 if not beta_private.active_member_session() or not exists(select 1 from beta_public.profiles where id=u and disabled_at is null and age_attested and accepted_version<>'') or not exists(select 1 from beta_fantasy.members where user_id=u and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Preview membership or session required'; end if;
 if exists(select 1 from auth.users au where au.id=u and (to_jsonb(au)->>'banned_until')::timestamptz>clock_timestamp()) then raise exception 'Account banned'; end if;
 if admin_required and (coalesce(auth.jwt()->>'aal','')<>'aal2' or not exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin'))) then raise exception 'Admin MFA required'; end if;
 return u; end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.preview_command(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; result jsonb:='{}'; prior beta_fantasy.requests; d beta_fantasy.pack_definitions; pack beta_fantasy.packs; chosen beta_fantasy.editions; l beta_fantasy.listings; tr beta_fantasy.trades; comp beta_fantasy.competitions; item record; i integer; cid uuid; ref uuid; snap jsonb; ids uuid[]; weights double precision; draw double precision; selected_tier text; slot_position text; fee bigint; score_rules jsonb; stats jsonb; n bigint; pid uuid; is_admin boolean;
begin
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.actor(false);
 if request_id is null then raise exception 'Request ID required'; end if;
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=preview_command.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused'; end if; return prior.result; end if;
 is_admin:=action like 'admin_%'; if is_admin then perform beta_fantasy.actor(true); end if;
 if action in('claim_starter','buy_pack') then
  if action='claim_starter' then
   if exists(select 1 from beta_fantasy.packs a join beta_fantasy.pack_definitions b on b.id=a.definition_id where a.user_id=u and b.name='Starter') then raise exception 'Starter already claimed'; end if;
   select * into strict d from beta_fantasy.pack_definitions where name='Starter' and version=1;
  else select * into strict d from beta_fantasy.pack_definitions where id=(p->>'definition_id')::uuid and name not in('Starter','Replacement'); end if;
  if d.status<>'active' or clock_timestamp()<d.starts_at or clock_timestamp()>=d.ends_at or d.sold>=d.max_quantity then raise exception 'Pack unavailable'; end if;
  insert into beta_fantasy.packs(user_id,definition_id,request_id) values(u,d.id,request_id) returning id into ref;
  update beta_fantasy.pack_definitions set sold=sold+1 where id=d.id;
  perform beta_fantasy.prepare_pack(ref,u);
  result:=jsonb_build_object('pack_id',ref);
 elsif action='open_pack' then
  select * into strict pack from beta_fantasy.packs where id=(p->>'pack_id')::uuid and user_id=u;
  if pack.opened_at is null then
   select * into strict d from beta_fantasy.pack_definitions where id=pack.definition_id;
   update beta_fantasy.packs set opened_at=clock_timestamp() where id=pack.id;
   perform beta_fantasy.social(u,'Opened a '||d.name||' pack in Fantasy Cards Preview.');
  end if;
  select jsonb_build_object('pack_id',pack.id,'cards',jsonb_agg(card_id order by slot)) into result from beta_fantasy.pack_items where pack_id=pack.id;
 elsif action='list' then
  cid:=(p->>'card_id')::uuid; perform beta_fantasy.transferable(cid,u);
  insert into beta_fantasy.listings(card_id,seller,price,fee_bps) select cid,u,(p->>'price')::bigint,fee_bps from beta_fantasy.settings returning id into ref;
  perform beta_fantasy.social(u,'Listed a card for test credits in Fantasy Cards Preview.'); result:=jsonb_build_object('listing_id',ref);
 elsif action='cancel_listing' then
  update beta_fantasy.listings set state='cancelled' where id=(p->>'listing_id')::uuid and seller=u and state='active'; if not found then raise exception 'Active owned listing required'; end if;
 elsif action='buy' then
  select * into strict l from beta_fantasy.listings where id=(p->>'listing_id')::uuid;
  if l.state<>'active' or l.seller=u then raise exception 'Listing unavailable'; end if;
  perform beta_fantasy.transferable(l.card_id,l.seller);
  fee:=(l.price*l.fee_bps+5000)/10000;
  insert into beta_fantasy.sales(listing_id,buyer,seller,price,fee) values(l.id,u,l.seller,l.price,fee) returning id into ref;
  perform beta_fantasy.money('sale',ref,array[u::text,l.seller::text,'system:fee'],array[-l.price,l.price-fee,fee]);
  perform beta_fantasy.transfer(l.card_id,l.seller,u,'sale',ref,l.price);
  update beta_fantasy.listings set state='sold' where id=l.id;
  perform beta_fantasy.social(u,'Acquired a card on the test-credit marketplace.');
 elsif action='offer_trade' then
  pid:=(p->>'recipient')::uuid;
  if not exists(select 1 from beta_fantasy.members where user_id=pid and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Recipient unavailable'; end if;
  if jsonb_array_length(p->'give') not between 1 and 30 or jsonb_array_length(p->'receive') not between 1 and 30 then raise exception 'Both trade sides required'; end if;
  insert into beta_fantasy.trades(sender,recipient) values(u,pid) returning id into ref;
  for item in select value::uuid as id,u as owner from jsonb_array_elements_text(p->'give') union all select value::uuid,pid from jsonb_array_elements_text(p->'receive') loop
   perform beta_fantasy.transferable(item.id,item.owner);
   insert into beta_fantasy.trade_items values(ref,item.id,item.owner);
  end loop; result:=jsonb_build_object('trade_id',ref);
 elsif action in('accept_trade','decline_trade','cancel_trade') then
  select * into strict tr from beta_fantasy.trades where id=(p->>'trade_id')::uuid;
  if tr.state<>'pending' or tr.expires_at<=clock_timestamp() then raise exception 'Trade unavailable or expired'; end if;
  if (action='cancel_trade' and tr.sender<>u) or (action<>'cancel_trade' and tr.recipient<>u) then raise exception 'Trade permission denied'; end if;
  if action='accept_trade' then
   for item in select * from beta_fantasy.trade_items where trade_id=tr.id order by card_id loop perform beta_fantasy.transferable(item.card_id,item.from_user); end loop;
   for item in select * from beta_fantasy.trade_items where trade_id=tr.id order by card_id loop perform beta_fantasy.transfer(item.card_id,item.from_user,case when item.from_user=tr.sender then tr.recipient else tr.sender end,'trade',tr.id); end loop;
   perform beta_fantasy.social(u,'Completed a card trade in Fantasy Cards Preview.');
  end if;
  update beta_fantasy.trades set state=case action when 'accept_trade' then 'accepted' when 'decline_trade' then 'declined' else 'cancelled' end where id=tr.id;
 elsif action='save_lineup' then
  select * into strict comp from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
  if clock_timestamp()<comp.opens_at or clock_timestamp()>=comp.locks_at or comp.scored_at is not null then raise exception 'Lineup locked or entry closed'; end if;
  select array_agg(value::uuid) into ids from jsonb_array_elements_text(p->'cards'); snap:=beta_fantasy.lineup(comp.id,u,ids);
  insert into beta_fantasy.entries(competition_id,user_id,cards,snapshot) values(comp.id,u,ids,snap) on conflict(competition_id,user_id) do update set cards=excluded.cards,snapshot=excluded.snapshot,updated_at=clock_timestamp();
 elsif action='admin_credit' then
  pid:=(p->>'user_id')::uuid; if not exists(select 1 from beta_fantasy.members where user_id=pid) or (p->>'amount')::bigint not between 1 and 1000000 then raise exception 'Invalid credit grant'; end if;
  perform beta_fantasy.money('admin_credit',request_id,array['system:issuance',pid::text],array[-(p->>'amount')::bigint,(p->>'amount')::bigint]);
 elsif action='admin_status' then
  pid:=(p->>'player_id')::uuid;
  update beta_fantasy.players set status=p->>'status' where id=pid; if not found then raise exception 'Player missing'; end if;
  insert into beta_fantasy.status_events(player_id,status,actor) values(pid,p->>'status',u);
  if p->>'status' in('retired','delisted') then
   -- Before lock, retirement invalidates the saved entry; rebuild explicitly, never substitute.
   delete from beta_fantasy.entries en using beta_fantasy.competitions co where en.competition_id=co.id and co.locks_at>clock_timestamp() and exists(select 1 from jsonb_array_elements(en.snapshot) si where (si->>'player_id')::uuid=pid);
   insert into beta_fantasy.replacements(card_id,user_id) select a.id,a.owner_id from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id where e.player_id=pid on conflict do nothing;
  end if;
 elsif action='admin_replacement' then
  cid:=(p->>'card_id')::uuid;
  select user_id into strict pid from beta_fantasy.replacements where card_id=cid and pack_id is null;
  select * into strict d from beta_fantasy.pack_definitions where name='Replacement' and version=1;
  if d.sold>=d.max_quantity then raise exception 'Replacement stock exhausted'; end if;
  insert into beta_fantasy.packs(user_id,definition_id,request_id) values(pid,d.id,request_id) returning id into ref;
  update beta_fantasy.pack_definitions set sold=sold+1 where id=d.id;
  perform beta_fantasy.prepare_pack(ref,pid);
  update beta_fantasy.replacements set pack_id=ref where card_id=cid; result:=jsonb_build_object('pack_id',ref);
 elsif action='admin_simulate' then
  select * into strict comp from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
  if comp.scored_at is not null or clock_timestamp()<comp.locks_at then raise exception 'Round must be locked and unscored'; end if;
  select rules into strict score_rules from beta_fantasy.scoring_rules where id=comp.scoring_id;
  for item in select a.* from beta_fantasy.players a where sport=comp.sport order by id loop
   n:=('x'||substr(md5((p->>'seed')||':'||item.id::text),1,8))::bit(32)::bigint;
   stats:=jsonb_build_object('minutes',case when item.status='active' then 90 else 0 end,'goals',case when n%7=0 then 1 else 0 end,'assists',case when n%5=0 then 1 else 0 end,'conceded',n%4,'saves',n%8,'yellow',case when n%11=0 then 1 else 0 end,'red',0,'own_goals',0);
   stats:=coalesce((select ri.stats from beta_fantasy.round_inputs ri where ri.competition_id=comp.id and ri.player_id=item.id),stats);
   insert into beta_fantasy.round_scores values(comp.id,item.id,comp.scoring_id,stats,beta_fantasy.score(stats,item.position,score_rules));
  end loop;
  insert into beta_fantasy.results(competition_id,user_id,entry_id,score,rank,championship_points)
  select comp.id,x.user_id,x.id,x.total,x.place,coalesce((comp.awards->>(x.place::integer-1))::integer,0) from (
   select e.id,e.user_id,sum(s.score)::integer total,rank() over(order by sum(s.score) desc)::integer place from beta_fantasy.entries e cross join lateral jsonb_array_elements(e.snapshot) a join beta_fantasy.round_scores s on s.competition_id=e.competition_id and s.player_id=(a->>'player_id')::uuid where e.competition_id=comp.id group by e.id,e.user_id
  ) x;
  update beta_fantasy.competitions set scored_at=clock_timestamp(),seed=(p->>'seed')::integer where id=comp.id;
  for item in select user_id from beta_fantasy.results where competition_id=comp.id and rank=1 loop perform beta_fantasy.social(item.user_id,'Won '||comp.name||' in Fantasy Cards Preview.'); end loop;
 elsif action='admin_stats' then
  if not exists(select 1 from beta_fantasy.competitions co join beta_fantasy.players pl on pl.sport=co.sport where co.id=(p->>'competition_id')::uuid and pl.id=(p->>'player_id')::uuid and co.scored_at is null) then raise exception 'Unscored sport round required'; end if;
  if not ((p->'stats') ?& array['minutes','goals','assists','conceded','saves','yellow','red','own_goals']) or exists(select 1 from jsonb_each_text(p->'stats') x where x.value::integer<0 or x.value::integer>150) then raise exception 'Invalid event statistics'; end if;
  insert into beta_fantasy.round_inputs values((p->>'competition_id')::uuid,(p->>'player_id')::uuid,p->'stats',u) on conflict(competition_id,player_id) do update set stats=excluded.stats,actor=excluded.actor;
 elsif action='admin_scoring' then
  if (p->'rules'->>'save_group')::integer<=0 or (p->'rules'->>'conceded_group')::integer<=0 then raise exception 'Positive scoring divisor required'; end if;
  insert into beta_fantasy.scoring_rules(version,rules)values(p->>'version',p->'rules');
 elsif action='admin_player' then
  if not exists(select 1 from beta_fantasy.sports where id=p->>'sport' and positions ? (p->>'position')) then raise exception 'Sport position invalid'; end if;
  insert into beta_fantasy.players(name,sport,position,team,colour,shirt,first_season,prospect_rank) values(p->>'name',p->>'sport',p->>'position',p->>'team',p->>'colour',(p->>'shirt')::integer,p->>'first_season',(p->>'prospect_rank')::integer) returning id into ref; result:=jsonb_build_object('player_id',ref);
 elsif action='admin_edition' then
  if p->>'kind'='first_year' and not exists(select 1 from beta_fantasy.players where id=(p->>'player_id')::uuid and first_season=p->>'season') then raise exception 'First Year must match first eligible season'; end if;
  insert into beta_fantasy.editions(player_id,tier,season,kind,max_supply,prospect_rank,launch_at,status) values((p->>'player_id')::uuid,p->>'tier',p->>'season',p->>'kind',(p->>'max_supply')::integer,(p->>'prospect_rank')::integer,(p->>'launch_at')::timestamptz,'draft') returning id into ref; result:=jsonb_build_object('edition_id',ref);
 elsif action='admin_lock_edition' then
  update beta_fantasy.editions set locked_at=clock_timestamp(),status='launched' where id=(p->>'edition_id')::uuid and locked_at is null and status='draft'; if not found then raise exception 'Unlocked draft edition required'; end if;
 elsif action='admin_pack' then
  select array_agg(value::uuid) into ids from jsonb_array_elements_text(p->'pool');
  if cardinality(ids) is null or cardinality(ids)=0 or exists(select 1 from unnest(ids) x where not exists(select 1 from beta_fantasy.editions where id=x and status='launched')) then raise exception 'Launched edition pool required'; end if;
  if exists(select 1 from jsonb_each_text(p->'weights') w where w.value::numeric<0 or not exists(select 1 from beta_fantasy.tiers where id=w.key)) or (select sum(value::numeric) from jsonb_each_text(p->'weights'))<>100 then raise exception 'Tier probabilities must sum to 100'; end if;
  for item in select key,value from jsonb_each_text(coalesce(p->'guarantees','{}')) loop
   if item.key !~ '^[0-9]+$' or item.key::integer>=jsonb_array_length(p->'slots') or not exists(select 1 from beta_fantasy.tiers where id=item.value) then raise exception 'Invalid guarantee slot'; end if;
  end loop;
  insert into beta_fantasy.pack_definitions(name,version,slots,pool,weights,guarantees,price,max_quantity,tradeable,starts_at,ends_at) values(p->>'name',(p->>'version')::integer,p->'slots',ids,p->'weights',coalesce(p->'guarantees','{}'),(p->>'price')::bigint,(p->>'max_quantity')::integer,(p->>'tradeable')::boolean,(p->>'starts_at')::timestamptz,(p->>'ends_at')::timestamptz) returning id into ref;result:=jsonb_build_object('definition_id',ref);
 elsif action='admin_fee' then
  update beta_fantasy.settings set fee_bps=(p->>'fee_bps')::integer;
 elsif action='admin_competition' then
  insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id) values(p->>'name','football',p->>'season',(p->>'round')::integer,(p->>'locks_at')::timestamptz,p->'rules',(select id from beta_fantasy.scoring_rules where version=coalesce(p->>'scoring_version','football-demo-v1'))) returning id into ref; result:=jsonb_build_object('competition_id',ref);
 else raise exception 'Unknown fantasy action'; end if;
 if is_admin then insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p); end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;begin
 if action in('claim_starter','open_nfl_starter') and exists(select 1 from sports_feed.nfl_control where enabled)
 and exists(select 1 from sports_feed.weekly_core_control where legacy_closed_at is not null) then
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() then raise exception 'Active session required';end if;
 if not exists(select 1 from sports_feed.nfl_starter_entitlements where user_id=u)
 and not exists(select 1 from sports_feed.nfl_allocations where user_id=u)
 then raise exception 'Your free Core cards are in Weekly starter pack under My Packs';end if;
 end if;
 return beta_fantasy.production_command_before_weekly_cutover(action,p,request_id);
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command_before_customer_pack(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; prior beta_fantasy.requests; answer jsonb; c beta_fantasy.competitions; ids uuid[]; snap jsonb; counts jsonb;begin
 if not exists(select 1 from sports_feed.nfl_control where enabled) then return beta_fantasy.production_command_before_nfl(action,p,request_id);end if;
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() then raise exception 'Active session required';end if;
 if request_id is null or p is null or jsonb_typeof(p)<>'object' then raise exception 'Request required';end if;
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command_before_customer_pack.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused';end if;return prior.result;end if;
 if action='claim_starter' then
 if p<>'{}' then raise exception 'Empty starter payload required';end if;
 answer:=sports_feed.nfl_allocate(u);
 elsif action='save_lineup' and exists(select 1 from sports_feed.nfl_rounds where competition_id=(p->>'competition_id')::uuid and purpose='member') then
 select * into strict c from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
 if c.locks_at<=clock_timestamp() or c.opens_at>clock_timestamp() then raise exception 'Lineup locked';end if;
 if (select count(*) from jsonb_object_keys(p))<>2 or jsonb_typeof(p->'cards')<>'array' then raise exception 'Exact lineup payload required';end if;
 select array_agg(value::uuid) into ids from jsonb_array_elements_text(p->'cards');
 if cardinality(ids)<>7 or (select count(distinct x) from unnest(ids)x)<>7 then raise exception 'Seven distinct owned cards required';end if;
 select jsonb_agg(jsonb_build_object('card_id',a.id,'player_id',e.player_id,'tier',e.tier,'position',pl.position,'season',e.season,'kind',e.kind,'provider_id',np.provider_id,'name',pl.name,'team',np.current_team) order by a.id),
 jsonb_build_object('QB',count(*) filter(where pl.position='QB'),'RB',count(*) filter(where pl.position='RB'),'WR',count(*) filter(where pl.position='WR'),'TE',count(*) filter(where pl.position='TE'),'unique',count(distinct pl.id)) into snap,counts
 from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players pl on pl.id=e.player_id join sports_feed.nfl_players np on np.player_id=pl.id
 where a.id=any(ids) and a.owner_id=u and pl.sport='nfl' and np.source_status='ACT' and np.observed_at>clock_timestamp()-interval '72 hours'
 and exists(select 1 from sports_feed.nfl_rounds nr,jsonb_array_elements(nr.fixtures) f where nr.competition_id=c.id and f->'playerIds' ? pl.id::text)
 and not exists(select 1 from beta_fantasy.listings where card_id=a.id and state='active');
 if coalesce(jsonb_array_length(snap),0)<>7 or (counts->>'unique')::int<>7 or (counts->>'QB')::int<>1 or (counts->>'RB')::int<2 or (counts->>'WR')::int<2 or (counts->>'TE')::int<1 then raise exception 'NFL requires QB, 2 RB, 2 WR, TE and RB/WR/TE FLEX; owned eligible mapped players only';end if;
 insert into beta_fantasy.entries(competition_id,user_id,cards,snapshot) values(c.id,u,ids,snap) on conflict(competition_id,user_id) do update set cards=excluded.cards,snapshot=excluded.snapshot,updated_at=clock_timestamp();
 insert into sports_feed.stream_members(stream_id,user_id) select stream_id,u from sports_feed.nfl_rounds where competition_id=c.id on conflict do nothing;
 answer:=jsonb_build_object('saved',true,'competition_id',c.id);
 elsif action in('admin_stats','admin_simulate') and exists(select 1 from sports_feed.nfl_rounds where competition_id=(p->>'competition_id')::uuid) then raise exception 'NFL results require authorised source reconciliation';
 elsif action='claim_daily' then raise exception 'Daily card rewards unavailable in the free NFL beta';
 else return beta_fantasy.production_command_before_nfl(action,p,request_id);
 end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,answer);return answer;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command_before_nfl(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare u uuid; begin
  perform pg_advisory_xact_lock(71820342);
  u:=beta_fantasy.production_eligible();
  -- Recover a committed result after a release transition. The original entry
  -- point still checks current membership/MFA and exact action/payload identity.
  if exists(select 1 from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command.request_id) then
    return beta_fantasy.production_command_v1(action,p,request_id);
  end if;
  if action in('save_lineup','admin_stats','admin_simulate') and not exists(
    select 1 from beta_fantasy.production_rounds where competition_id=(p->>'competition_id')::uuid
      and release_channel=beta_fantasy.production_channel()) then
    raise exception 'Current release round required';
  end if;
  return beta_fantasy.production_command_v1(action,p,request_id);
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command_before_rarity(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; prior beta_fantasy.requests; entitlement sports_feed.nfl_starter_entitlements; answer jsonb;
begin
 if not exists(select 1 from sports_feed.nfl_control where enabled) or action not in('claim_starter','open_nfl_starter') then return beta_fantasy.production_command_before_customer_pack(action,p,request_id);end if;
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() then raise exception 'Active session required';end if;
 if request_id is null or p is distinct from '{}'::jsonb then raise exception 'Empty starter payload and request required';end if;
 insert into beta_fantasy.members(user_id,expires_at) values(u,'infinity') on conflict do nothing;
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command_before_rarity.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused';end if;return prior.result;end if;
 insert into sports_feed.nfl_starter_entitlements(user_id) values(u) on conflict do nothing;
 select * into strict entitlement from sports_feed.nfl_starter_entitlements where user_id=u for update;
 if action='open_nfl_starter' then
  answer:=sports_feed.nfl_allocate(u);
  if entitlement.opened_at is null then update sports_feed.nfl_starter_entitlements set opened_at=clock_timestamp() where user_id=u;end if;
  answer:=answer||jsonb_build_object('pack_id',entitlement.id,'opened',true);
 else answer:=jsonb_build_object('pack_id',entitlement.id,'opened',entitlement.opened_at is not null or exists(select 1 from sports_feed.nfl_allocations where user_id=u));end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,answer);
 return answer;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command_before_seven(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; c beta_fantasy.competitions; prior beta_fantasy.requests; ids uuid[]; snap jsonb; inventory jsonb; answer jsonb; cfg jsonb; rules_hash text;begin
 if action<>'save_lineup' or not exists(select 1 from beta_fantasy.competitions where id=(p->>'competition_id')::uuid and rules->>'inventory_scope'='invited-nfl-test-v2') then
 return beta_fantasy.production_command_before_rarity(action,p,request_id);end if;
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() or not exists(select 1 from credits_sandbox.access where user_id=u and enabled) then raise exception 'Test competition admission required';end if;
 -- Identical ordering to financial transactions: lineup lock, then aggregate.
 perform 1 from credits_sandbox.state where id for update;
 select * into strict c from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command_before_seven.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused';end if;return prior.result;end if;
 if request_id is null or (select count(*) from jsonb_object_keys(p))<>2 or jsonb_typeof(p->'cards')<>'array' then raise exception 'Exact lineup payload required';end if;
 if c.locks_at<=clock_timestamp() or c.opens_at>clock_timestamp() or c.scored_at is not null then raise exception 'Lineup locked';end if;
 if not exists(select 1 from sports_feed.nfl_rounds where competition_id=c.id and purpose='member' and locked_at is null) then raise exception 'Member round required';end if;
 select body->'period'->'rules',body->'audits'->0->>'payloadHash' into cfg,rules_hash from sports_feed.journal where stream_id=(select stream_id from sports_feed.nfl_rounds where competition_id=c.id) order by revision desc limit 1;
 if cfg->>'version'<>'docked-nfl-rarity-test-v1' or cfg->>'rarityVersion' is distinct from c.rules->>'rarity_version' then raise exception 'Registered rarity rules required';end if;
 select array_agg(value::uuid) into ids from jsonb_array_elements_text(p->'cards');
 if cardinality(ids)<>7 or (select count(distinct x) from unnest(ids)x)<>7 then raise exception 'Seven distinct owned cards required';end if;
 inventory:=sports_feed.rarity_inventory(u);
 -- Free Core is optional position coverage, never a paid allocation or reroll.
 select inventory||coalesce(jsonb_agg(jsonb_build_object('id',a.id,'card_id',a.id,'edition_id',e.id,'owner_id',u,'player_id',permanent.id,'tier','CORE','position',pl.position,'season',e.season,'kind',e.kind,'provider_id',np.provider_id,'name',pl.name,'team',np.current_team,'sport','nfl','status','active','listed',false,'serial',a.serial,'max_supply',0,'tradeable',a.tradeable,'colour',pl.colour,'shirt',pl.shirt,'created_at',a.created_at,'acquired_at',a.created_at,'multiplier',1,'multiplierTenths',10,'rarityVersion',cfg->>'rarityVersion')),'[]') into inventory
 from beta_fantasy.cards a join beta_fantasy.editions e on e.id=a.edition_id join beta_fantasy.players pl on pl.id=e.player_id join sports_feed.nfl_players np on np.player_id=pl.id join credits_sandbox.permanent_players permanent on permanent.provider_id=np.provider_id
 where a.owner_id=u and e.tier='CORE' and np.source_status='ACT' and np.observed_at>clock_timestamp()-interval '72 hours' and not exists(select 1 from beta_fantasy.listings where card_id=a.id and state='active');
 select jsonb_agg(v||jsonb_build_object('card_id',v->>'id','rules_version',cfg->>'version') order by v->>'id') into snap from jsonb_array_elements(inventory)v
 where (v->>'id')::uuid=any(ids) and v->>'status'='active' and not (v->>'listed')::boolean
 and exists(select 1 from sports_feed.nfl_rounds nr,jsonb_array_elements(nr.fixtures) f where nr.competition_id=c.id and f->'playerIds' ? (v->>'player_id'));
 if coalesce(jsonb_array_length(snap),0)<>7 or (select count(distinct v->>'player_id') from jsonb_array_elements(snap)v)<>7
 or (select count(*) from jsonb_array_elements(snap)v where v->>'position'='QB')<>1
 or (select count(*) from jsonb_array_elements(snap)v where v->>'position'='RB')<2
 or (select count(*) from jsonb_array_elements(snap)v where v->>'position'='WR')<2
 or (select count(*) from jsonb_array_elements(snap)v where v->>'position'='TE')<1
 or exists(select 1 from jsonb_array_elements(snap)v where v->>'position' not in('QB','RB','WR','TE')) then
 raise exception 'Choose owned, opened, unlisted cards: QB, 2 RB, 2 WR, TE and RB/WR/TE FLEX; one card per mapped player';end if;
 insert into beta_fantasy.entries(competition_id,user_id,cards,snapshot) values(c.id,u,ids,snap) on conflict(competition_id,user_id) do update set cards=excluded.cards,snapshot=excluded.snapshot,updated_at=clock_timestamp();
 insert into sports_feed.stream_members(stream_id,user_id) select stream_id,u from sports_feed.nfl_rounds where competition_id=c.id on conflict do nothing;
 answer:=jsonb_build_object('saved',true,'competition_id',c.id);
 insert into beta_fantasy.requests values(u,request_id,action,p,answer);
 insert into beta_private.audit_events(actor,action,subject,details) values(u::text,'rarity_team_saved',c.id::text,jsonb_build_object('cards',ids,'rules_version',cfg->>'version','request',request_id));
 return answer;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command_before_weekly_cutover(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if action='seven_admin_control' then return sports_feed.seven_admin_control(p,request_id);end if;
 if action in('seven_draft','seven_enter','seven_withdraw') then return sports_feed.seven_command(action,p,request_id);end if;
 if action='save_lineup' and exists(select 1 from beta_fantasy.competitions where id=(p->>'competition_id')::uuid and rules->>'lineup_version' is not null) then raise exception 'Use explicit draft or competition entry';end if;
 return beta_fantasy.production_command_before_seven(action,p,request_id);
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_command_v1(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; prior beta_fantasy.requests; result jsonb; pack uuid; comp_id uuid; definition uuid; previous beta_fantasy.pack_definitions; policy beta_fantasy.production_policy; claim beta_fantasy.daily_claims; period_key date; outcome text:='not_due'; count_claims integer; begin
 perform pg_advisory_xact_lock(71820342);
 u:=beta_fantasy.production_eligible();
 if request_id is null or p is null or jsonb_typeof(p)<>'object' then raise exception 'Request ID and payload required'; end if;
 if action is null or action not in('claim_starter','claim_daily','open_pack','save_lineup','admin_reward_policy','admin_stats','admin_simulate','admin_free_round','admin_starter_stock') then raise exception 'Action unavailable in free-play production'; end if;
 insert into beta_fantasy.members(user_id,expires_at) values(u,'infinity') on conflict(user_id) do nothing;
 perform beta_fantasy.actor(action like 'admin_%');
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=production_command_v1.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused'; end if; return prior.result; end if;
 if action in('open_pack','save_lineup','admin_stats','admin_simulate') then
  if action<>'open_pack' and not exists(select 1 from beta_fantasy.production_rounds where competition_id=(p->>'competition_id')::uuid) then raise exception 'Production round required'; end if;
  if action='open_pack' and not exists(select 1 from beta_fantasy.packs pa join beta_fantasy.production_definitions pd on pa.definition_id=pd.definition_id where pa.id=(p->>'pack_id')::uuid and pa.user_id=u) then raise exception 'Own production pack required'; end if;
  return beta_fantasy.preview_command(action,p,request_id);
 elsif action='claim_starter' then
  if p<>'{}'::jsonb then raise exception 'Starter payload must be empty'; end if;
  select pack_id into pack from beta_fantasy.starter_claims where user_id=u;
  if pack is null then
   pack:=beta_fantasy.production_pack((select starter_definition from beta_fantasy.production_catalog),u);
   insert into beta_fantasy.starter_claims values(u,pack,clock_timestamp());
  end if;
  result:=jsonb_build_object('pack_id',pack);
 elsif action='claim_daily' then
  if p<>'{}'::jsonb then raise exception 'Daily payload must be empty'; end if;
  if not exists(select 1 from beta_fantasy.starter_claims where user_id=u) then raise exception 'Claim starter before daily rewards'; end if;
  period_key:=(clock_timestamp() at time zone 'UTC')::date;
  select * into claim from beta_fantasy.daily_claims where user_id=u and period=period_key;
  if not found then
   select * into strict policy from beta_fantasy.production_policy order by version desc limit 1;
   select count(*)+1 into count_claims from beta_fantasy.daily_claims where user_id=u;
   if count_claims%policy.card_every=0 then
    if (select count(*) from beta_fantasy.daily_claims where period=period_key and pack_id is not null)>=policy.daily_card_limit then outcome:='daily_limit';
    else
     -- Only expected stock exhaustion falls back to points; unexpected failures abort.
     if exists(select 1 from beta_fantasy.pack_definitions d join beta_fantasy.production_catalog pc on pc.reward_definition=d.id where d.price=0 and not d.tradeable and d.sold<d.max_quantity and d.status='active' and clock_timestamp()>=d.starts_at and clock_timestamp()<d.ends_at and exists(select 1 from beta_fantasy.editions e join beta_fantasy.players pl on pl.id=e.player_id where e.id=any(d.pool) and e.tier='CORE' and e.status='launched' and e.launch_at<=clock_timestamp() and e.issued<e.max_supply and pl.status not in('retired','delisted'))) then
      pack:=beta_fantasy.production_pack((select reward_definition from beta_fantasy.production_catalog),u); outcome:='awarded';
     else outcome:='stock_unavailable'; end if;
    end if;
   end if;
   insert into beta_fantasy.daily_claims(user_id,period,points,policy_version,pack_id,card_outcome) values(u,period_key,policy.daily_points,policy.version,pack,outcome) returning * into claim;
  end if;
  result:=jsonb_build_object('claim_id',claim.id,'period',claim.period,'points',claim.points,'pack_id',claim.pack_id,'card_outcome',claim.card_outcome);
 elsif action='admin_starter_stock' then
  if p->>'quantity' is null or (select count(*) from jsonb_object_keys(p))<>1 or (p->>'quantity')::integer not between 1 and 1000 then raise exception 'Bounded starter quantity required'; end if;
  select d.* into strict previous from beta_fantasy.pack_definitions d join beta_fantasy.production_catalog pc on pc.starter_definition=d.id;
  if previous.sold<previous.max_quantity then raise exception 'Existing starter allocation must be exhausted'; end if;
  insert into beta_fantasy.pack_definitions(name,version,slots,pool,weights,guarantees,price,max_quantity,tradeable,ends_at)
   values('Starter',previous.version+1,previous.slots,previous.pool,previous.weights,previous.guarantees,0,(p->>'quantity')::integer,false,previous.ends_at) returning id into definition;
  insert into beta_fantasy.production_definitions values(definition,'starter');
  update beta_fantasy.production_catalog set starter_definition=definition;
  result:=jsonb_build_object('definition_id',definition);
  insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p);
 elsif action='admin_free_round' then
  if not (p ?& array['name','season','round','locks_at']) or (select count(*) from jsonb_object_keys(p))<>4 or length(p->>'name') not between 2 and 80 or length(p->>'season') not between 1 and 20 or (p->>'round')::integer not between 1 and 1000 or (p->>'locks_at')::timestamptz<=clock_timestamp() or (p->>'locks_at')::timestamptz>clock_timestamp()+interval '90 days' then raise exception 'Valid future free round required'; end if;
  insert into beta_fantasy.competitions(name,sport,season,round,locks_at,rules,scoring_id,prize) values(p->>'name','football',p->>'season',(p->>'round')::integer,(p->>'locks_at')::timestamptz,'{"duplicates":false}',(select id from beta_fantasy.scoring_rules where version='football-free-play-v1'),'No cash prize') returning id into comp_id;
  insert into beta_fantasy.production_rounds values(comp_id);
  result:=jsonb_build_object('competition_id',comp_id);
  insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p);
 else
  if not (p ?& array['daily_points','card_every','daily_card_limit']) or (select count(*) from jsonb_object_keys(p))<>3 then raise exception 'Exact reward policy required'; end if;
  insert into beta_fantasy.production_policy(daily_points,card_every,daily_card_limit,actor) values((p->>'daily_points')::integer,(p->>'card_every')::integer,(p->>'daily_card_limit')::integer,u) returning jsonb_build_object('version',version) into result;
  insert into beta_fantasy.admin_events(actor,action,payload) values(u,action,p);
 end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_eligible_before_owner_gameplay()
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
  if current_setting('docked.fantasy_channel',true) is distinct from beta_fantasy.production_channel() then
    raise exception 'Production release channel mismatch';
  end if;
  return beta_fantasy.production_eligible_v1();
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_eligible_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid(); s beta_fantasy.settings; begin
 select * into strict s from beta_fantasy.settings;
 if s.deployment_mode<>'production' or not s.enabled or current_setting('docked.fantasy_production',true) is distinct from s.production_ref or coalesce(current_setting('docked.fantasy_preview',true),'')<>'' then raise exception 'Production Fantasy context required'; end if;
 perform 1 from beta_public.profiles where id=u for share;
 if not beta_private.active_member_session() or not exists(select 1 from beta_public.profiles where id=u and disabled_at is null and age_attested and accepted_version=s.terms_version) then raise exception 'Verified current-consent account required'; end if;
 if not coalesce((select granted and version=s.privacy_version from beta_private.consent_events where user_id=u and purpose='privacy' order by created_at desc,id desc limit 1),false) then raise exception 'Current privacy consent required'; end if;
 if exists(select 1 from auth.users au where au.id=u and (to_jsonb(au)->>'banned_until')::timestamptz>clock_timestamp()) then raise exception 'Account banned'; end if;
 return u;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_pack(definition uuid, u uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare d beta_fantasy.pack_definitions; pack uuid; begin
 select * into strict d from beta_fantasy.pack_definitions where id=definition for update;
 if d.price<>0 or d.tradeable or d.status<>'active' or clock_timestamp()<d.starts_at or clock_timestamp()>=d.ends_at or d.sold>=d.max_quantity then raise exception 'Free pack unavailable'; end if;
 insert into beta_fantasy.packs(user_id,definition_id,request_id) values(u,d.id,gen_random_uuid()) returning id into pack;
 update beta_fantasy.pack_definitions set sold=sold+1 where id=d.id;
 perform beta_fantasy.prepare_pack(pack,u);
 return pack;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_read_state_before_continuity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb;u uuid;begin
 s:=beta_fantasy.production_read_state_before_weekly_cutover();
 if s->>'nfl_beta'='true' and exists(select 1 from sports_feed.weekly_core_control where legacy_closed_at is not null) then
 u:=beta_fantasy.production_eligible();
 s:=jsonb_set(s,'{rewards,starter_entitled}',to_jsonb(exists(select 1 from sports_feed.nfl_starter_entitlements where user_id=u) or exists(select 1 from sports_feed.nfl_allocations where user_id=u)));
 end if;
 return s;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_read_state_before_customer_pack()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb;begin
 s:=beta_fantasy.production_read_state_nfl_initial();
 if not coalesce((s->>'nfl_beta')::boolean,false) then return s;end if;
 return s||jsonb_build_object('my_championship_points',0,'leaderboard',jsonb_build_object('rows','[]'::jsonb),
 'cards',coalesce((select jsonb_agg(c||jsonb_build_object('team',p.current_team,'edition_team',p.edition_team,'provider_id',p.provider_id,'status',case when p.source_status='ACT' and p.observed_at>clock_timestamp()-interval '72 hours' then 'active' else 'unavailable' end)) from jsonb_array_elements(s->'cards')c join sports_feed.nfl_players p on p.player_id=(c->>'player_id')::uuid),'[]'));
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_read_state_before_free_core()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb;context jsonb;u uuid;begin
 s:=beta_fantasy.production_read_state_before_continuity();
 if s->'seven' is null then return s;end if;
 context:=sports_feed.seven_continue_teams();u:=(s->>'user_id')::uuid;
 return s||jsonb_build_object('seven',(s->'seven')||context||jsonb_build_object('drafts',coalesce((select jsonb_agg(to_jsonb(d)-'user_id') from beta_fantasy.round_drafts d where user_id=u),'[]')));
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_read_state_before_rarity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; u uuid; opened boolean;
begin
 result:=beta_fantasy.production_read_state_before_customer_pack();
 if result->>'nfl_beta' is distinct from 'true' then return result;end if;
 u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() then raise exception 'Active session required';end if;
 insert into sports_feed.nfl_starter_entitlements(user_id) values(u) on conflict do nothing;
 opened:=exists(select 1 from sports_feed.nfl_allocations where user_id=u);
 return jsonb_set(result,'{rewards}',coalesce(result->'rewards','{}')||jsonb_build_object('starter_entitled',true,'starter_claimed',opened,'starter_opened',opened));
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.production_read_state_nfl_initial()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare state jsonb; u uuid; comps jsonb; summaries jsonb; details jsonb;begin
 state:=beta_fantasy.production_read_state_before_nfl();if not exists(select 1 from sports_feed.nfl_control where enabled) then return state;end if;u:=(state->>'user_id')::uuid;
 select coalesce(jsonb_agg(to_jsonb(c)-'prize' order by c.locks_at),'[]') into comps from beta_fantasy.competitions c join sports_feed.nfl_rounds n on n.competition_id=c.id where n.purpose='member';
 select coalesce(jsonb_agg(jsonb_build_object('competition_id',n.competition_id,'user_id',u,'score',(r->>'centipoints')::numeric/100,'rank',r->'rank','championship_points',0,'status',r->>'status')),'[]') into summaries
 from sports_feed.nfl_rounds n join lateral(select calculated from sports_feed.journal where stream_id=n.stream_id order by revision desc limit 1)j on true,
 jsonb_array_elements(j.calculated->'rows')r where n.purpose='member' and r->>'member'=u::text and r->>'centipoints' is not null;
 select coalesce(jsonb_agg(jsonb_build_object('competition_id',n.competition_id,'cards',coalesce(d->'cards','[]'),'scores',
 coalesce((select jsonb_agg(jsonb_build_object('player_id',p->>'playerId','score',(p->>'centipoints')::numeric/100,'stats','{}'::jsonb,'scoring_version',j.calculated->>'rulesVersion','rules','{}'::jsonb,'matches',p->'matches')) from jsonb_array_elements(r->'players')p),'[]'))),'[]') into details
 from sports_feed.nfl_rounds n join lateral(select calculated from sports_feed.journal where stream_id=n.stream_id order by revision desc limit 1)j on true,
 jsonb_array_elements(j.calculated->'rows')r left join lateral(select value d from jsonb_array_elements(state->'round_details') where value->>'competition_id'=n.competition_id::text)orig on true
 where n.purpose='member' and r->>'member'=u::text;
 return state||jsonb_build_object('nfl_beta',true,'competitions',comps,'results',summaries,'round_details',details,
 'cards',coalesce((select jsonb_agg(c) from jsonb_array_elements(state->'cards')c where exists(select 1 from sports_feed.nfl_players p where p.player_id=(c->>'player_id')::uuid)),'[]'),
 'archived_card_count',(select count(*) from jsonb_array_elements(state->'cards')c where not exists(select 1 from sports_feed.nfl_players p where p.player_id=(c->>'player_id')::uuid)),
 'packs','[]'::jsonb,'rewards',(state->'rewards')||jsonb_build_object('starter_claimed',exists(select 1 from sports_feed.nfl_allocations where user_id=u),'daily_available',false));
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.save_prize_schedule(p_competition uuid, p_scope text, p_items jsonb, p_publish boolean, p_revision integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c beta_fantasy.competitions;s beta_fantasy.prize_schedules; old_value jsonb;wanted_week integer;begin
 perform beta_fantasy.member_release_admin();
 if p_reason is null or length(btrim(p_reason)) not between 1 and 500 or p_scope not in ('weekly','season') or p_scope is null or p_publish is null then raise exception 'Scope and reason required';end if;
 perform beta_fantasy.validate_prizes(p_items);
 select * into strict c from beta_fantasy.competitions where id=p_competition;
 if c.sport not in ('nfl','football','afl','nrl') or coalesce(c.rules->>'mode','') not in ('SALARY_CAP','OPEN') then raise exception 'Unsupported competition';end if;
 if c.sport in ('afl','nrl') then
   if c.scored_at is not null or c.locks_at<=clock_timestamp() then raise exception 'Historical prize rules are immutable';end if;
   if p_publish and (not coalesce((c.rules->'round_reward_policy'->>'active')::boolean,false)
    or c.rules->'round_reward_policy'->>'tiePolicy' is null
    or c.rules->'round_reward_policy'->'items' is distinct from p_items)
   then raise exception 'Approved activation and saved tie policy required; draft only';end if;
   if exists(select 1 from jsonb_array_elements(p_items) i where i->>'type'='pack' and
    coalesce(i->>'productVersion','') not in ('standard-9-'||c.sport||'-real-roster-beta-v1','premium-9-'||c.sport||'-real-roster-beta-v1'))
   then raise exception 'Correct sport-specific reward product required';end if;
  end if;
  wanted_week:=case when p_scope='weekly' then c.round else 0 end;
 perform pg_advisory_xact_lock(hashtextextended('prizes:'||c.sport||':'||(c.rules->>'mode')||':'||c.season||':'||p_scope||':'||wanted_week,762));
 select * into s from beta_fantasy.prize_schedules where sport=c.sport and mode=c.rules->>'mode' and season=c.season and scope=p_scope and week=wanted_week for update;
 if coalesce(s.revision,0) is distinct from p_revision then raise exception 'Schedule changed; refresh before saving';end if;
 old_value:=case when s.id is null then null else to_jsonb(s) end;
 insert into beta_fantasy.prize_schedules(sport,mode,season,scope,week,competition_id,draft,published,effective_at)
 values(c.sport,c.rules->>'mode',c.season,p_scope,wanted_week,c.id,p_items,case when p_publish then p_items end,case when p_publish then clock_timestamp() end)
 on conflict(sport,mode,season,scope,week) do update set draft=excluded.draft,
 published=case when p_publish then excluded.draft else beta_fantasy.prize_schedules.published end,
 effective_at=case when p_publish then clock_timestamp() else beta_fantasy.prize_schedules.effective_at end,
 revision=beta_fantasy.prize_schedules.revision+1 returning * into s;
 insert into beta_private.audit_events(actor,action,subject,details) values(auth.uid()::text,case when p_publish then 'prize_schedule_published' else 'prize_schedule_drafted' end,s.id::text,jsonb_build_object('previous',old_value,'resulting',to_jsonb(s),'reason',btrim(p_reason)));
 return to_jsonb(s);
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.social(u uuid, body text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare sid uuid; begin
 select id into sid from beta_private.social_profiles where user_id=u and status='active' and visibility='members';
 if sid is not null and beta_private.community_feature_allowed(u,'community_social') then
  insert into beta_private.social_posts(author_id,kind,body,sport) values(sid,'celebration',case when (select deployment_mode from beta_fantasy.settings)='production' then replace(body,'Fantasy Cards Preview','Fantasy Cards') else body end,'football');
 end if;
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.swap_card(cid uuid, u uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare rev bigint;begin
 if not beta_private.admitted(u) or not beta_private.beta_gameplay_identity(u) then raise exception 'Swap participant unavailable';end if;
 if not exists(select 1 from beta_fantasy.members m join beta_public.profiles p on p.id=m.user_id where m.user_id=u and m.revoked_at is null and m.expires_at>clock_timestamp() and p.disabled_at is null) then raise exception 'Swap participant unavailable';end if;
 if not exists(select 1 from beta_fantasy.cards where id=cid and owner_id=u) then raise exception 'Card ownership changed';end if;
 if exists(select 1 from beta_fantasy.pack_items i join beta_fantasy.packs p on p.id=i.pack_id where i.card_id=cid and p.opened_at is null) then raise exception 'Open the pack before swapping';end if;
 if sports_feed.card_entry_reserved(cid) then raise exception 'Remove card from unsettled lineup before swapping';end if;
 -- Existing free beta cards stay non-transferable outside this specifically authorised sandbox.
 select count(*) into rev from beta_fantasy.ownership_events where card_id=cid;return rev;end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.swap_command(a text, p jsonb, req uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s beta_fantasy.swaps; ids uuid[];begin
 perform pg_advisory_xact_lock(71820342);
 perform pg_advisory_xact_lock(71820342);
 perform beta_fantasy.swap_actor();
 if exists(select 1 from sports_feed.nfl_control where enabled) then
  if a in('reserve_pack','practice_credit','fee_mode') then raise exception 'Extra packs and balances unavailable in the free NFL beta';end if;
  if a='offer' then ids:=array[(p->>'give_card')::uuid,(p->>'take_card')::uuid];
  elsif a='accept' then select * into s from beta_fantasy.swaps where id=(p->>'swap_id')::uuid;ids:=array[s.give_card,s.take_card];end if;
  if a in('offer','accept') and (select count(*) from beta_fantasy.cards c join sports_feed.nfl_players n on n.edition_id=c.edition_id where c.id=any(ids))<>2 then raise exception 'Only real NFL beta cards can be swapped';end if;
 end if;
 return beta_fantasy.swap_command_before_nfl(a,p,req);
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.swap_command_before_nfl(a text, p jsonb, req uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare u uuid;peer uuid;s beta_fantasy.swaps; prior beta_fantasy.swap_requests;w jsonb;result jsonb;id uuid;g uuid;t uuid;gr bigint;tr bigint;fee integer;begin
 perform pg_advisory_xact_lock(71820342);u:=beta_fantasy.swap_actor();
 if req is null then raise exception 'Request identity required';end if;
 select * into prior from beta_fantasy.swap_requests where user_id=u and request_id=req;
 if found then if prior.action<>a or prior.payload<>p then raise exception 'Request identity reused with different fields';end if;return prior.result;end if;
 select case when owner_id=u then tester_id else owner_id end into peer from beta_private.two_person_control where two_person_control.id;
 if not exists(select 1 from beta_private.friends_control where enabled) and not beta_private.admitted(peer) then raise exception 'Other participant has not completed admission';end if;
 if exists(select 1 from beta_private.friends_control where enabled) and a in('fee_mode','practice_credit') then raise exception 'Friends card swaps have no fees or cash balances';end if;
 if a='fee_mode' then
 if coalesce(auth.jwt()->>'aal','')<>'aal2' or not exists(select 1 from beta_private.two_person_control where owner_id=u) then raise exception 'Owner MFA required';end if;
 if p->>'mode' not in('scheduled','free','paid') or p->>'mode' is null then raise exception 'Invalid fee mode';end if;
 update beta_fantasy.swap_policy set override_mode=p->>'mode',override_until=case when p->>'mode'='scheduled' then null else clock_timestamp()+interval '1 hour' end,revision=revision+1 where true;
 insert into beta_fantasy.swap_policy_events(actor,mode,revision,expires_at) select u,override_mode,revision,override_until from beta_fantasy.swap_policy;
 result:=jsonb_build_object('ok',true,'mode',p->>'mode');
 elsif a='offer' then
 g:=(p->>'give_card')::uuid;t:=(p->>'take_card')::uuid;
 if exists(select 1 from beta_private.friends_control where enabled) then select c.owner_id into peer from beta_fantasy.cards c where c.id=t;if peer is null or peer=u then raise exception 'Choose another admitted participant card';end if;end if;
 gr:=beta_fantasy.swap_card(g,u);tr:=beta_fantasy.swap_card(t,peer);w:=beta_fantasy.swap_window();fee:=(w->>'fee_cents')::int;
 if p->>'fee_cents' is distinct from fee::text or p->>'policy_revision' is distinct from w->>'revision' then raise exception 'Fee changed; review again';end if;
 insert into beta_fantasy.swaps(sender,recipient,give_card,take_card,give_revision,take_revision,fee_cents,policy_revision,expires_at)
 values(u,peer,g,t,gr,tr,fee,(w->>'revision')::bigint,(w->>'expires_at')::timestamptz) returning swaps.id into id;
 result:=jsonb_build_object('ok',true,'swap_id',id,'state','pending');
 elsif a in('accept','reject','cancel') then
 select * into s from beta_fantasy.swaps where swaps.id=(p->>'swap_id')::uuid for update;
 if not found or u not in(s.sender,s.recipient) then raise exception 'Swap unavailable';end if;
 if (a in('accept','reject') and u<>s.recipient) or (a='cancel' and u<>s.sender) then raise exception 'Swap permission denied';end if;
 if s.state<>'pending' then raise exception 'Swap already completed';end if;
 if a='accept' then
 w:=beta_fantasy.swap_window();
 if clock_timestamp()>=s.expires_at or s.policy_revision<>(w->>'revision')::bigint or s.fee_cents<>(w->>'fee_cents')::int then raise exception 'Offer expired; request a new offer';end if;
 if p->>'fee_cents' is distinct from s.fee_cents::text then raise exception 'Review the participant fee';end if;
 if beta_fantasy.swap_card(s.give_card,s.sender)<>s.give_revision or beta_fantasy.swap_card(s.take_card,s.recipient)<>s.take_revision then raise exception 'Stale card ownership; create a new offer';end if;
 if exists(select 1 from unnest(array[s.sender,s.recipient]) x where coalesce((select sum(amount_cents) from beta_fantasy.swap_ledger where user_id=x),0)<s.fee_cents) then raise exception 'Insufficient simulated balance';end if;
 update beta_fantasy.cards set owner_id=case when cards.id=s.give_card then s.recipient else s.sender end where cards.id in(s.give_card,s.take_card);
 insert into beta_fantasy.ownership_events(card_id,from_user,to_user,reason,reference,acquisition_price,prospect_rank)
 select c.id,case when c.id=s.give_card then s.sender else s.recipient end,c.owner_id,'two-person-sandbox-swap',s.id,null,pl.prospect_rank
 from beta_fantasy.cards c join beta_fantasy.editions e on e.id=c.edition_id join beta_fantasy.players pl on pl.id=e.player_id where c.id in(s.give_card,s.take_card);
 insert into beta_fantasy.swap_ledger(user_id,kind,amount_cents,reference) values(s.sender,'swap_fee',-s.fee_cents,s.id),(s.recipient,'swap_fee',-s.fee_cents,s.id);
 update beta_fantasy.listings set state='cancelled' where card_id in(s.give_card,s.take_card) and state='active';
 end if;
 update beta_fantasy.swaps set state=case a when 'accept' then 'accepted' when 'reject' then 'rejected' else 'cancelled' end,completed_at=clock_timestamp() where swaps.id=s.id returning * into s;
 result:=jsonb_build_object('ok',true,'swap_id',s.id,'state',s.state,'fee_cents',s.fee_cents);
 elsif a='reserve_pack' then
 select pack_id into id from beta_fantasy.swap_reserve_packs where user_id=u;
 if not found then
 id:=beta_fantasy.production_pack((select starter_definition from beta_fantasy.production_catalog),u);
 insert into beta_fantasy.swap_reserve_packs(user_id,pack_id) values(u,id);
 end if;
 result:=jsonb_build_object('ok',true,'pack_id',id,'beta_reserves_only',true);
 elsif a='practice_credit' then
 insert into beta_fantasy.swap_ledger(user_id,kind,amount_cents,reference) values(u,'practice_credit',10000,u) on conflict do nothing;
 result:=jsonb_build_object('ok',true,'practice_currency_only',true);
 else raise exception 'Unsupported sandbox action';end if;
 insert into beta_fantasy.swap_requests values(u,req,a,p,result);return result;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.swap_read_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb;u uuid;begin
 u:=beta_fantasy.swap_actor();
 perform pg_advisory_xact_lock(71820342);
 with expired as(update beta_fantasy.swaps set state='expired',completed_at=clock_timestamp() where state='pending' and expires_at<=clock_timestamp() and u in(sender,recipient) returning id,expires_at)
 insert into beta_private.audit_events(actor,action,subject,details) select u::text,'swap_expired',id::text,jsonb_build_object('previous','pending','result','expired','expires_at',expires_at,'reason','Server observed expiry; no transfer or fee') from expired;
 s:=beta_fantasy.swap_read_state_before_marketplace();return s;
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.swap_window()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare p beta_fantasy.swap_policy; n timestamptz:=clock_timestamp(); start_at timestamptz; boundary timestamptz; free boolean;begin
 if exists(select 1 from beta_private.friends_control where enabled) then return jsonb_build_object('free',true,'fee_cents',0,'revision',(select revision from beta_fantasy.swap_policy),'expires_at',n+interval '5 minutes','next_boundary',null,'server_time',n,'override_mode','friends-free');end if;
 select * into strict p from beta_fantasy.swap_policy where id;
 start_at:=p.epoch+floor(extract(epoch from(n-p.epoch))/2419200)*interval '28 days';
 free:=n<start_at+interval '48 hours';boundary:=case when free then start_at+interval '48 hours' else start_at+interval '28 days' end;
 if p.override_mode<>'scheduled' and p.override_until>n then free:=p.override_mode='free';boundary:=p.override_until;end if;
 return jsonb_build_object('free',free,'fee_cents',case when free then 0 else 250 end,'revision',p.revision,'expires_at',least(n+interval '5 minutes',boundary),'next_boundary',boundary,'server_time',n,'override_mode',case when p.override_until>n then p.override_mode else 'scheduled' end);
end$function$

CREATE OR REPLACE FUNCTION beta_fantasy.transfer(cid uuid, from_id uuid, to_id uuid, reason text, ref uuid, price bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 perform beta_fantasy.transferable(cid,from_id);
 update beta_fantasy.cards set owner_id=to_id where id=cid and owner_id=from_id;
 if not found then raise exception 'Ownership changed'; end if;
 insert into beta_fantasy.ownership_events(card_id,from_user,to_user,reason,reference,acquisition_price,prospect_rank) select cid,from_id,to_id,reason,ref,price,p.prospect_rank from beta_fantasy.cards c join beta_fantasy.editions e on e.id=c.edition_id join beta_fantasy.players p on p.id=e.player_id where c.id=cid;
 update beta_fantasy.listings set state='cancelled' where card_id=cid and state='active';
end $function$

CREATE OR REPLACE FUNCTION beta_fantasy.transferable(cid uuid, u uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ begin
 if not exists(select 1 from beta_fantasy.members m join beta_public.profiles p on p.id=m.user_id where m.user_id=u and m.revoked_at is null and m.expires_at>clock_timestamp() and p.disabled_at is null) then raise exception 'Card owner membership inactive'; end if;
 if exists(select 1 from beta_fantasy.pack_items pi join beta_fantasy.packs pa on pa.id=pi.pack_id where pi.card_id=cid and pa.opened_at is null) then raise exception 'Open the pack before transferring cards'; end if;
 if not exists(select 1 from beta_fantasy.cards where id=cid and owner_id=u and tradeable) then raise exception 'Tradeable owned card required'; end if;
 if sports_feed.card_entry_reserved(cid) then raise exception 'Card committed to lineup; remove before trading'; end if;
end $function$

CREATE OR REPLACE FUNCTION beta_private.accept_admission(p_token text, p_user uuid, p_session uuid, p_country text, p_state text, p_adult boolean, p_versions jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform 1 from beta_private.admission_control where id for update;
 if not exists(select 1 from beta_private.admission_control where enabled and testers_enabled)
 and not exists(select 1 from beta_private.designated_administrators where user_id=p_user)
 then raise exception 'External tester activation remains closed';end if;
 return beta_private.accept_admission_verified(p_token,p_user,p_session,p_country,p_state,p_adult,p_versions);
end$function$

CREATE OR REPLACE FUNCTION beta_private.accept_admission_verified(p_token text, p_user uuid, p_session uuid, p_country text, p_state text, p_adult boolean, p_versions jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare invite beta_private.admissions; control beta_private.admission_control;begin
 select * into strict control from beta_private.admission_control where id for update;
 if not control.enabled or control.policy_versions is distinct from p_versions then raise exception 'Current approved beta policies required';end if;
 if p_token is null or p_token !~ '^[a-f0-9]{64}$' then raise exception 'Invalid invitation';end if;
 select * into invite from beta_private.admissions where token_digest=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if not found or invite.user_id is distinct from p_user or invite.status in('revoked','suspended') then raise exception 'Invalid invitation';end if;
 if not exists(select 1 from auth.users u join auth.sessions s on s.user_id=u.id where u.id=p_user and s.id=p_session
 and lower(to_jsonb(u)->>'email')=invite.email and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false)
 and (s.not_after is null or s.not_after>clock_timestamp()) and coalesce((to_jsonb(u)->>'banned_until')::timestamptz,'-infinity')<=clock_timestamp()) then
 raise exception 'Verified active invitation session required';end if;
 if p_country is distinct from 'AU' or p_state is null or p_state<>all(array['ACT','NSW','NT','QLD','SA','TAS','VIC','WA']) or p_adult is distinct from true then raise exception 'Australian adult eligibility required';end if;
 -- Recovery of a committed acceptance is allowed only for the same verified
 -- identity/session context; it never creates a second account or consumes a slot.
 if invite.status='accepted' then return invite.id;end if;
 if invite.expires_at<=clock_timestamp() then raise exception 'Invitation expired';end if;
 update beta_private.admissions set status='accepted',accepted_at=clock_timestamp(),country=p_country,state=p_state,age_attested=true,
 policy_digest=control.policy_digest,policy_versions=p_versions where id=invite.id;
 insert into beta_private.admission_events(admission_id,action,actor) values(invite.id,'accepted',p_user::text);
 return invite.id;
end$function$

CREATE OR REPLACE FUNCTION beta_private.accept_customer_admission(p_user uuid, p_session uuid, p_country text, p_state text, p_adult boolean, p_versions jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare control beta_private.admission_control; invite beta_private.admissions;begin
 select * into strict control from beta_private.admission_control where id for update;
 if not control.enabled or not control.testers_enabled or not exists(select 1 from beta_private.friends_control where enabled) or not beta_private.customer_signup_identity(p_user) then raise exception 'Verified invited account required';end if;
 if p_versions is distinct from control.policy_versions then raise exception 'Current policies required';end if;
 select * into strict invite from beta_private.admissions where user_id=p_user for update;
 if not exists(select 1 from auth.sessions where id=p_session and user_id=p_user and (not_after is null or not_after>clock_timestamp())) then raise exception 'Active session required';end if;
 if p_country is distinct from 'AU' or p_state is null or p_state<>all(array['ACT','NSW','NT','QLD','SA','TAS','VIC','WA']) or p_adult is distinct from true then raise exception 'Australian adult eligibility required';end if;
 if invite.status='accepted' then return invite.id;end if;
 if invite.status<>'reserved' or invite.expires_at<=clock_timestamp() then raise exception 'Invitation unavailable';end if;
 update beta_private.admissions set status='accepted',accepted_at=clock_timestamp(),country=p_country,state=p_state,age_attested=true,policy_digest=control.policy_digest,policy_versions=p_versions where id=invite.id;
 insert into beta_private.admission_events(admission_id,action,actor) values(invite.id,'accepted',p_user::text);
 return invite.id;
end$function$

CREATE OR REPLACE FUNCTION beta_private.admin_record_detail(p_category text, p_id text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '4s'
AS $function$
declare actor uuid:=auth.uid(); staff_role text; permitted text[]; title text; source text;
 fields jsonb; events jsonb:='[]'; doc jsonb; item jsonb; more boolean;
begin
 if actor is null or not coalesce(beta_private.active_member_session(),false) or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'Staff MFA required';end if;
 select role into staff_role from beta_private.roles where user_id=actor;
 permitted:=case staff_role
 when 'owner' then array['members','cards','packs','transactions','competitions','moderation']
 when 'admin' then array['members','cards','packs','competitions','moderation']
 when 'auditor' then array['members','cards','packs','competitions','moderation']
 when 'editor' then array['competitions','moderation']
 when 'analyst' then array['competitions'] else array[]::text[] end;
 if cardinality(permitted)=0 then raise exception 'Role denied';end if;
 if p_category is null or not p_category=any(permitted) then raise exception 'Category denied';end if;
 if p_id is null or length(btrim(p_id))=0 or length(p_id)>160 or p_id ~ '[[:cntrl:]]' or p_page is null or p_page<1 or p_page>100 then raise exception 'Invalid record';end if;

 if p_category='members' then
  select coalesce(nullif(s.display_name,''),'Member'),'Member admission and social records',jsonb_build_object(
   'Record ID',p.id,'Handle',s.handle,'Created at',p.created_at,'Account status',case when p.disabled_at is null then 'Enabled' else 'Restricted' end,
   'Restricted at',p.disabled_at,'Social status',s.status,'Admission status',a.status,'Invitation created at',a.created_at,'Admission accepted at',a.accepted_at,
   'Assigned staff role',r.role)
  into title,source,fields from beta_public.profiles p
  left join beta_private.social_profiles s on s.user_id=p.id
  left join beta_private.admissions a on a.user_id=p.id
  left join beta_private.roles r on r.user_id=p.id where p.id::text=p_id;
  select coalesce(jsonb_agg(to_jsonb(e) order by e.at desc,e.id),'[]') into events from (
   select * from (
    select 'admission:'||e.id id,e.created_at at,'Admission: '||e.action event,'Recorded admission transition' detail
    from beta_private.admission_events e join beta_private.admissions a on a.id=e.admission_id where a.user_id::text=p_id
    union all select 'moderation:'||e.id,e.created_at,'Moderation: '||e.decision,'Recorded profile enforcement'
    from beta_private.social_moderation_events e join beta_private.social_profiles s on s.id=e.target_id
    where e.target_type='profile' and s.user_id::text=p_id
   ) h order by at desc,id limit 21 offset (p_page-1)*20
  ) e;
 elsif p_category='competitions' then
  select case when c.rules->>'lineup_version' is not null and c.rules->>'mode' in ('SALARY_CAP','OPEN') then
    (case c.rules->>'mode' when 'SALARY_CAP' then 'Traditional' else 'All-Star' end)||' · '||c.season||' · Week '||c.round else c.name end,
   'Competition schedule and aggregate entry records',jsonb_build_object('Record ID',c.id,'Sport',c.sport,'Season',c.season,'Week',c.round,
    'Opens at',c.opens_at,'Locks at',c.locks_at,'Scored at',c.scored_at,'Scoring rule ID',c.scoring_id,
    'Entry count',(select count(*) from beta_fantasy.entries e where e.competition_id=c.id),
    'Result count',(select count(*) from beta_fantasy.results r where r.competition_id=c.id),
    'Schedule state',case when now()<c.opens_at then 'Upcoming' when now()<c.locks_at then 'Entry window' else 'Lock time passed; player locks remain authoritative' end)
  into title,source,fields from beta_fantasy.competitions c where c.id::text=p_id;
  -- No cards, snapshots, slot assignments or draft fields are projected, even
  -- for the owner. Scored_at is evidence of a scoring run, not finality.
 elsif p_category='moderation' then
  select initcap(r.target_type)||' report','Moderation classification',jsonb_build_object('Record ID',r.id,'Target type',r.target_type,'Status',r.status,'Category',r.reason,'Created at',r.created_at)
   into title,source,fields from beta_private.social_reports r where r.id::text=p_id;
  select coalesce(jsonb_agg(to_jsonb(e) order by e.at desc,e.id),'[]') into events from (
   select e.id::text id,e.created_at at,e.decision event,'Recorded staff decision' detail from beta_private.social_moderation_events e
   where e.report_id::text=p_id order by e.created_at desc,e.id limit 21 offset (p_page-1)*20
  ) e;
 elsif p_category='cards' then
  select p.name,'Legacy issued collectible',jsonb_build_object('Record ID',c.id,'Player',p.name,'Sport',p.sport,'Position',p.position,'Rarity',e.tier,
   'Serial',c.serial,'Edition',e.id,'Maximum supply',e.max_supply,'Issued supply',e.issued,'Owner reference',c.owner_id,'Issued at',c.created_at,'Tradeable',c.tradeable)
   into title,source,fields from beta_fantasy.cards c join beta_fantasy.editions e on e.id=c.edition_id join beta_fantasy.players p on p.id=e.player_id where c.id::text=p_id;
  if title is not null then
   select coalesce(jsonb_agg(to_jsonb(e) order by e.at desc,e.id),'[]') into events from (
    select e.id::text id,e.created_at at,'Ownership: '||e.reason event,concat_ws(' · ','From '||coalesce(e.from_user::text,'issuance'),'To '||e.to_user::text,'Reference '||e.reference::text) detail
    from beta_fantasy.ownership_events e where e.card_id::text=p_id order by e.created_at desc,e.id limit 21 offset (p_page-1)*20
   ) e;
  else
   select s.document into doc from credits_sandbox.state s where s.document#>array['economy','instances',p_id] is not null or s.document#>array['economy','definitions',p_id] is not null;
   item:=doc#>array['economy','instances',p_id];
   if item is not null then
    title:=coalesce(doc#>>array['economy','players',item->>'playerId','name'],'Player record'); source:='Current issued collectible and immutable ownership history';
    fields:=jsonb_build_object('Record ID',p_id,'Player',title,'Rarity',item->>'rarity','Serial',item->'serial','Lifetime supply',item->'lifetimeCap',
     'Edition',item->>'definition','Issued at',to_timestamp((item->>'mintedAt')::numeric/1000),'Owner reference',doc#>>array['commerce','cards',p_id,'owner']);
    select coalesce(jsonb_agg(to_jsonb(e) order by e.at desc,e.id desc),'[]') into events from (
     select h.n::text id,to_timestamp((h.value->>'at')::numeric/1000) at,'Ownership transfer' event,
      concat_ws(' · ','From '||coalesce(h.value->>'from','issuance'),'To '||(h.value->>'to'),'Reference '||(h.value->>'reference')) detail
     from jsonb_array_elements(coalesce(doc#>array['cards',p_id,'history'],'[]')) with ordinality h(value,n)
     order by (h.value->>'at')::numeric desc,h.n desc limit 21 offset (p_page-1)*20
    ) e;
   else
    item:=doc#>array['economy','definitions',p_id];
    if item is not null then
     title:=coalesce(doc#>>array['economy','players',item->>'playerId','name'],'Player record');source:='Current collectible edition';
     fields:=jsonb_build_object('Record ID',p_id,'Player',title,'Rarity',item->>'rarity','Issued supply',item->'issued');
    end if;
   end if;
  end if;
 elsif p_category='packs' then
  select d.name,'Legacy pack issuance',jsonb_build_object('Record ID',p.id,'Member reference',p.user_id,'Configuration ID',p.definition_id,
   'Issued at',p.created_at,'Opened at',p.opened_at,'Status',case when p.opened_at is null then 'Unopened' else 'Opened' end,
   'Issued card count',(select count(*) from beta_fantasy.pack_items i where i.pack_id=p.id))
   into title,source,fields from beta_fantasy.packs p join beta_fantasy.pack_definitions d on d.id=p.definition_id where p.id::text=p_id;
  if title is null then
   select 'Weekly Core Pack','Weekly reward entitlement',jsonb_build_object('Record ID',p.id,'Member reference',p.user_id,'Sport',p.sport,'Reward period',p.period,
    'Policy',p.policy,'Due at',p.due_at,'Issued at',p.issued_at,'Opened at',p.opened_at,'Status',case when p.opened_at is null then 'Unopened' else 'Opened' end,'Price','Free reward')
    into title,source,fields from sports_feed.weekly_core_packs p where p.id::text=p_id;
  end if;
  if title is null then
   select s.document into doc from credits_sandbox.state s where s.document#>array['economy','packs',p_id] is not null or s.document#>array['economy','products',p_id] is not null;
   item:=doc#>array['economy','packs',p_id];
   if item is not null then
    title:=item#>>'{product,name}';source:='Purchase-time pack configuration snapshot';
    fields:=jsonb_build_object('Record ID',p_id,'Member reference',item->>'member','Configuration version',item#>>'{product,version}',
     'Configuration hash',item->>'configurationHash','Card count',item#>'{product,cards}','Price (test credits)',item#>'{product,priceCredits}',
     'Issued at',to_timestamp((item->>'createdAt')::numeric/1000),'Opened at',to_timestamp((item->>'openedAt')::numeric/1000),
     'Status',case when item->>'openedAt' is null then 'Unopened' else 'Opened' end);
   else
    item:=doc#>array['economy','products',p_id];
    if item is not null then
     title:=item->>'name';source:='Pack configuration';
     fields:=jsonb_build_object('Record ID',p_id,'Version',item->>'version','Sport',item->>'sport','Card count',item->'cards','Price (test credits)',item->'priceCredits',
      'Status',item->>'status','Duplicate-player policy',item->>'duplicatePlayers','Supply exhaustion policy',item->>'exhaustion',
      'Effective at',to_timestamp((item->>'effectiveAt')::numeric/1000),'Expires at',to_timestamp((item->>'expiresAt')::numeric/1000));
    end if;
   end if;
  end if;
 elsif p_category='transactions' then
  select j.value into item from credits_sandbox.state s cross join lateral jsonb_array_elements(coalesce(s.document->'journal','[]')) j where j.value->>'id'=p_id;
  if item is not null then
   title:='Test-credit ledger record';source:='Immutable credit journal · test credits have no cash value';
   fields:=jsonb_build_object('Record ID',p_id,'Policy',item->>'policy','Recorded at',to_timestamp((item->>'at')::numeric/1000),'Unit','Test credits',
    'Line count',jsonb_array_length(item->'lines'),'Journal line total',(select sum((l->>'credits')::numeric) from jsonb_array_elements(item->'lines') l));
   select coalesce(jsonb_agg(to_jsonb(e) order by e.ordinal),'[]') into events from (
    select l.n ordinal,l.n::text id,to_timestamp((item->>'at')::numeric/1000) at,'Ledger line' event,
     concat_ws(' · ',l.value->>'account',(l.value->>'credits')||' test credits') detail
    from jsonb_array_elements(item->'lines') with ordinality l(value,n) order by l.n limit 21 offset (p_page-1)*20
   ) e;
  end if;
 end if;
 if title is null then return null;end if;
 more:=jsonb_array_length(events)>20;
 select coalesce(jsonb_agg(e.value order by e.n),'[]') into events from jsonb_array_elements(events) with ordinality e(value,n) where e.n<=20;
 return jsonb_build_object('id',p_id,'category',p_category,'title',title,'source',source,'fields',fields,'history',events,'page',p_page,'hasMore',more);
end $function$

CREATE OR REPLACE FUNCTION beta_private.admin_search(p_query text, p_category text DEFAULT 'all'::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '4s'
AS $function$
declare actor uuid:=auth.uid(); staff_role text; permitted text[]; selected text[]; result jsonb;
begin
 if actor is null or not coalesce(beta_private.active_member_session(),false) or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'Staff MFA required'; end if;
 select role into staff_role from beta_private.roles where user_id=actor;
 permitted:=case staff_role
  when 'owner' then array['members','cards','packs','transactions','competitions','moderation']
  when 'admin' then array['members','cards','packs','competitions','moderation']
  when 'auditor' then array['members','cards','packs','competitions','moderation']
  when 'editor' then array['competitions','moderation']
  when 'analyst' then array['competitions'] else array[]::text[] end;
 if cardinality(permitted)=0 then raise exception 'Role denied'; end if;
 if p_category is null or (p_category<>'all' and not p_category=any(permitted)) then raise exception 'Category denied';end if;
 p_query:=btrim(coalesce(p_query,''));
 if length(p_query)>120 or p_page is null or p_page<1 or p_page>100 then raise exception 'Invalid search';end if;
 if length(p_query)<2 then return '[]'::jsonb;end if;
 selected:=case when p_category='all' then permitted else array[p_category] end;
 with records as (
  select p.id::text id,'members'::text category,coalesce(nullif(s.display_name,''),'Member') title,
   concat_ws(' · ',case when p.disabled_at is null then 'Account enabled' else 'Account restricted' end,case when s.handle is not null then '@'||s.handle end) detail
   from beta_public.profiles p left join beta_private.social_profiles s on s.user_id=p.id where 'members'=any(selected)
  union all select c.id::text,'cards',p.name,concat_ws(' · ',upper(p.sport),p.position,e.tier,'#'||c.serial)
   from beta_fantasy.cards c join beta_fantasy.editions e on e.id=c.edition_id join beta_fantasy.players p on p.id=e.player_id where 'cards'=any(selected)
  union all select i.key,'cards',coalesce(s.document#>>array['economy','players',i.value->>'playerId','name'],'Player record'),
   concat_ws(' · ',upper(s.document#>>array['economy','players',i.value->>'playerId','sport']),i.value->>'rarity','#'||(i.value->>'serial'))
   from credits_sandbox.state s cross join lateral jsonb_each(coalesce(s.document#>'{economy,instances}','{}')) i where 'cards'=any(selected)
  union all select d.key,'cards',coalesce(s.document#>>array['economy','players',d.value->>'playerId','name'],'Player record'),
   concat_ws(' · ','Edition',d.value->>'rarity',(d.value->>'issued')||' issued')
   from credits_sandbox.state s cross join lateral jsonb_each(coalesce(s.document#>'{economy,definitions}','{}')) d where 'cards'=any(selected)
  union all select p.id::text,'packs',d.name,case when p.opened_at is null then 'Unopened · legacy pack' else 'Opened · legacy pack' end
   from beta_fantasy.packs p join beta_fantasy.pack_definitions d on d.id=p.definition_id where 'packs'=any(selected)
  union all select p.key,'packs',p.value#>>'{product,name}',case when p.value->>'openedAt' is null then 'Unopened · test-credit purchase' else 'Opened · test-credit purchase' end
   from credits_sandbox.state s cross join lateral jsonb_each(coalesce(s.document#>'{economy,packs}','{}')) p where 'packs'=any(selected)
  union all select p.key,'packs',p.value->>'name',concat_ws(' · ','Configuration',p.value->>'version',(p.value->>'cards')||' cards',(p.value->>'priceCredits')||' test credits')
   from credits_sandbox.state s cross join lateral jsonb_each(coalesce(s.document#>'{economy,products}','{}')) p where 'packs'=any(selected)
  union all select p.id::text,'packs','Weekly Core Pack',case when p.opened_at is null then 'Unopened · free reward' else 'Opened · free reward' end
   from sports_feed.weekly_core_packs p where 'packs'=any(selected)
  union all select j.value->>'id','transactions','Credit ledger record',concat_ws(' · ',j.value->>'policy','Test credits · no cash value')
   from credits_sandbox.state s cross join lateral jsonb_array_elements(coalesce(s.document->'journal','[]')) j where 'transactions'=any(selected)
  union all select c.id::text,'competitions',case when c.rules->>'lineup_version' is not null and c.rules->>'mode' in ('SALARY_CAP','OPEN') then
    (case c.rules->>'mode' when 'SALARY_CAP' then 'Traditional' else 'All-Star' end)||' · '||c.season||' · Week '||c.round else c.name end,
   concat_ws(' · ',upper(c.sport),c.season,'Week '||c.round) from beta_fantasy.competitions c where 'competitions'=any(selected)
  union all select r.id::text,'moderation',initcap(r.target_type)||' report',concat_ws(' · ',r.status,r.reason)
   from beta_private.social_reports r where 'moderation'=any(selected)
 ), matches as (
  select distinct id,category,title,detail from records where strpos(lower(concat_ws(' ',id,title,detail)),lower(p_query))>0
 ), page as (
  select * from matches order by case when lower(id)=lower(p_query) then 0 when lower(title)=lower(p_query) then 1 else 2 end,category,lower(title),id limit 21 offset (p_page-1)*20
 ) select coalesce(jsonb_agg(to_jsonb(page) order by case when lower(id)=lower(p_query) then 0 when lower(title)=lower(p_query) then 1 else 2 end,category,lower(title),id),'[]'::jsonb) into result from page;
 return result;
end $function$

CREATE OR REPLACE FUNCTION beta_private.admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='UPDATE' and old.status in('suspended','revoked') and new.user_id is null
 and (to_jsonb(new)-array['email','user_id'])=(to_jsonb(old)-array['email','user_id'])
 and beta_private.privacy_redaction_allowed(old.user_id,new.email) then return new;end if;
 update beta_private.admission_control set admission_revision=admission_revision+1 where id;
 if tg_op='DELETE' then raise exception 'Admission history is permanent'; end if;
 if tg_op='UPDATE' and (to_jsonb(new)-array['status','accepted_at','country','state','age_attested','policy_digest','policy_versions','token_digest','expires_at'])
 is distinct from (to_jsonb(old)-array['status','accepted_at','country','state','age_attested','policy_digest','policy_versions','token_digest','expires_at']) then
 raise exception 'Invitation identity and token are immutable'; end if;
 if tg_op='INSERT' or new.token_digest is distinct from old.token_digest then
 if new.expires_at<=clock_timestamp() or new.expires_at>clock_timestamp()+interval '7 days' or new.status<>'reserved' then raise exception 'Invitation expiry required within seven days';end if;
 end if;
 if new.administrator and (new.user_id is null or not exists(select 1 from beta_private.designated_administrators where user_id=new.user_id)) then
 raise exception 'Explicit designated administrator required'; end if;
 if tg_op='INSERT' and not new.administrator and (select count(*) from beta_private.admissions where not administrator)>=10 then
 raise exception 'Ten tester lifetime admission limit'; end if;
 if tg_op='UPDATE' and (old.status in('revoked','suspended') or (old.status='accepted' and new.status not in('revoked','suspended') and not (
 new.status='accepted' and (to_jsonb(new)-array['policy_digest','policy_versions'])=(to_jsonb(old)-array['policy_digest','policy_versions'])
 and new.user_id=auth.uid() and exists(select 1 from beta_private.admission_control c where c.enabled and c.policy_digest=new.policy_digest and c.policy_versions=new.policy_versions)
 and exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.user_id=new.user_id and s.id=(auth.jwt()->>'session_id')::uuid and (s.not_after is null or s.not_after>clock_timestamp()) and u.email_confirmed_at is not null and not coalesce(u.is_anonymous,false))
 and (not beta_private.gameplay_mfa_required(new.user_id) or auth.jwt()->>'aal'='aal2')))) then
 raise exception 'Invalid admission transition'; end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION beta_private.admitted_before_owner_gameplay(p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare ok boolean;begin
 perform 1 from beta_private.admission_control where id for share;
 perform 1 from beta_private.admissions where user_id=p_user for share;
 select exists(select 1 from beta_private.admissions a cross join beta_private.admission_control c
 where c.enabled and (a.administrator or c.testers_enabled) and a.user_id=p_user and a.status='accepted' and a.country='AU' and a.age_attested
 and a.policy_digest=c.policy_digest and a.policy_versions=c.policy_versions) into ok;
 return ok;
end$function$

