CREATE OR REPLACE FUNCTION beta_private.announcement_mutate(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<command>>
declare staff_role text; actor uuid:=auth.uid(); d beta_private.announcement_drafts%rowtype;
 old beta_private.announcement_events%rowtype; request_id uuid; draft_id uuid; action text; expected integer; result jsonb; next_status text;
begin
 staff_role:=beta_private.announcement_staff_role();
 if staff_role='auditor' then raise exception 'Role denied'; end if;
 if p is null or jsonb_typeof(p)<>'object' or (select count(*) from jsonb_object_keys(p)) not between 8 and 9 or (p - array['requestId','id','action','version','title','body','audience','reason','cta'])<>'{}'::jsonb
 or not p ?& array['requestId','id','action','version','title','body','audience','reason']
 or jsonb_typeof(p->'version')<>'number' or (p->>'version') !~ '^[0-9]+$'
 or jsonb_typeof(p->'title')<>'string' or jsonb_typeof(p->'body')<>'string'
 or jsonb_typeof(p->'reason')<>'string' or coalesce(p->>'audience','')<>'admitted'
 or length(btrim(p->>'title')) not between 1 and 120 or length(btrim(p->>'body')) not between 1 and 3000
 or length(btrim(p->>'reason')) not between 3 and 500 then raise exception 'Invalid announcement input'; end if;
 request_id:=(p->>'requestId')::uuid;draft_id:=(p->>'id')::uuid;action:=p->>'action';expected:=(p->>'version')::integer;
 if request_id is null or draft_id is null or action is null or action not in('create','save','submit','approve','request_changes','archive','restore','publish','pin','unpin') or expected>2147483646 then raise exception 'Invalid announcement input'; end if;
 if p ? 'cta' and p->'cta'<>'null'::jsonb and (jsonb_typeof(p->'cta')<>'string' or p->>'cta' not in('/fantasy/prizes','/fantasy/play','/fantasy/cards','/fantasy/market','/fantasy/results','/fantasy/test-wallet?view=packs')) then raise exception 'Internal destination required';end if;
 -- A repeated request returns its original result; reuse with different input fails.
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||request_id::text,0));
 select * into old from beta_private.announcement_events e where e.actor=command.actor and e.request_id=command.request_id;
 if found then
  if old.request<>p then raise exception 'Announcement request conflict';end if;
  return old.result;
 end if;
 if action='create' then
  perform pg_advisory_xact_lock(hashtextextended('announcement-create:'||actor::text,0));
  if expected<>0 or exists(select 1 from beta_private.announcement_drafts where id=draft_id) then raise exception 'Announcement version conflict'; end if;
  if (select count(*) from beta_private.announcement_drafts where created_by=actor and status<>'archived')>=100 then raise exception 'Archive an existing draft first';end if;
  insert into beta_private.announcement_drafts(id,title,body,audience,status,version,created_by,updated_by,last_edited_by)
  values(draft_id,btrim(p->>'title'),btrim(p->>'body'),'admitted','draft',1,actor,actor,actor) returning * into d;
 else
  select * into d from beta_private.announcement_drafts where id=draft_id for update;
  if not found or d.version<>expected then raise exception 'Announcement version conflict';end if;
  if staff_role='editor' and d.created_by<>actor then raise exception 'Role denied';end if;
  if action<>'save' and (d.title<>p->>'title' or d.body<>p->>'body' or (p ? 'cta' and d.cta is distinct from (p->>'cta'))) then raise exception 'Save content before changing review state';end if;
  next_status:=d.status;
  if action='save' then
   if d.status not in('draft','changes_requested','published') then raise exception 'Announcement state denied';end if;
   if d.published is not null and staff_role not in('owner','admin') then raise exception 'Publisher role required';end if;
   next_status:='draft';
  elsif action='submit' then
   if d.status not in('draft','changes_requested') then raise exception 'Announcement state denied';end if;
   next_status:='in_review';
  elsif action in('approve','request_changes') then
   if staff_role not in('owner','admin') or (staff_role<>'owner' and (actor=d.created_by or actor=d.last_edited_by)) then raise exception 'Owner or independent reviewer required';end if;
   if d.status<>'in_review' then raise exception 'Announcement state denied';end if;
   next_status:=case when action='approve' then 'approved' else 'changes_requested' end;
  elsif action='publish' then
   if staff_role not in('owner','admin') or d.status<>'approved' then raise exception 'Approved announcement and publisher role required';end if;
   next_status:='published';
  elsif action in('pin','unpin') then
   if staff_role not in('owner','admin') or d.published is null or d.status='archived' then raise exception 'Published announcement and publisher role required';end if;
  elsif action='archive' then
   if d.published is not null and staff_role not in('owner','admin') then raise exception 'Publisher role required';end if;
   if d.status='archived' then raise exception 'Announcement state denied';end if;
   next_status:='archived';
  elsif action='restore' then
   if d.status<>'archived' then raise exception 'Announcement state denied';end if;
   next_status:='draft';
  end if;
  update beta_private.announcement_drafts set title=btrim(p->>'title'),body=btrim(p->>'body'),status=next_status,version=version+1,updated_by=actor,last_edited_by=case when action='save' then actor else last_edited_by end,updated_at=clock_timestamp() where id=draft_id returning * into d;
 end if;
 update beta_private.announcement_drafts set
 cta=case when action in('save','create') and p ? 'cta' then p->>'cta' else cta end,
 published=case when action='publish' then jsonb_build_object('title',title,'body',body,'cta',cta) when action='restore' then null else published end,
 published_at=case when action='publish' then clock_timestamp() when action='restore' then null else published_at end,
 pinned=case when action='pin' then true when action in('unpin','archive','restore') then false else pinned end
 where id=draft_id returning * into d;
 result:=to_jsonb(d);
 insert into beta_private.announcement_events(draft_id,actor,request_id,action,reason,version,request,result)
 values(d.id,actor,request_id,action,btrim(p->>'reason'),d.version,p,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION beta_private.announcement_staff_role()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare staff_role text;
begin
 if auth.uid() is null or not coalesce(beta_private.active_member_session(),false) or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'Staff MFA required'; end if;
 select role into staff_role from beta_private.roles where user_id=auth.uid();
 if staff_role is null or staff_role not in('owner','admin','editor','auditor') then raise exception 'Role denied'; end if;
 return staff_role;
end $function$

CREATE OR REPLACE FUNCTION beta_private.assert_current_market_reference(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r beta_private.market_references;e beta_private.events;p beta_private.region_policies;checked timestamptz;expected text[];
begin
 select * into r from beta_private.market_references where id=p_id for share;
 perform beta_private.market_data_lock_sources(r.market_id); perform 1 from beta_private.markets where id=r.market_id for update;
 select e1.* into e from beta_private.events e1 join beta_private.markets m on m.event_id=e1.id where m.id=r.market_id for share of e1;
 select * into p from beta_private.region_policies where id=r.region_policy_id for share;
 perform 1 from beta_private.source_health where provider in(select provider from beta_private.odds_snapshots where market_id=r.market_id) for share;
 perform 1 from beta_private.bookmaker_eligibility where r.configuration->'pricingBookmakers' ? bookmaker or r.configuration->'availabilityBookmakers' ? bookmaker for share;
 checked:=clock_timestamp();
 if r.id is null or e.status<>'scheduled' or e.start_at<=checked+greatest(600,(r.configuration->>'cutoffSeconds')::int)*interval '1 second'
 or r.observed_at>checked or r.observed_at<checked-least(180,(r.configuration->>'maxAgeSeconds')::int)*interval '1 second'
 or not p.approved or p.effective_from>checked or p.effective_to<=checked or p.review_at<=checked then raise exception 'Reference no longer current'; end if;
 expected:=beta_private.reference_expected_availability(r.market_id,r.configuration,p.id,checked,r.selection);
 if to_jsonb(expected) is distinct from r.reference->'availability'->'sourceIds' then raise exception 'Reference availability changed'; end if;
 if r.reference->'pricing' is distinct from 'null'::jsonb then
  select array_agg(c.id order by c.bookmaker collate "C") into expected from beta_private.reference_cohort_sources(r.market_id,r.configuration,p.id,checked,'pricingBookmakers') c;
  if to_jsonb(expected) is distinct from r.reference->'pricing'->'sourceIds' then raise exception 'Reference pricing changed'; end if;
 end if;
end $function$

CREATE OR REPLACE FUNCTION beta_private.assert_football_comparison(p_prediction uuid, p_strategy text, p_reference uuid, p_purpose text, p_selection text)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p beta_private.football_model_attempts;s beta_private.strategy_versions;r beta_private.market_references;e beta_private.events;policy beta_private.region_policies;v numeric;checked timestamptz;
begin
 select * into s from beta_private.strategy_versions where id=p_strategy for share;select * into r from beta_private.market_references where id=p_reference for share;
 select * into p from beta_private.football_model_attempts where id=p_prediction for share;select * into e from beta_private.events where id=p.event_id for share;
 select * into policy from beta_private.region_policies where id=r.region_policy_id for share;
 perform beta_private.assert_football_prediction(p.id);perform beta_private.assert_current_market_reference(r.id);checked:=clock_timestamp();
 if not beta_private.scanner_strategy_allowed(s.id,p_purpose) or s.config->>'method' is distinct from 'football-independent-model' or p.model_version is distinct from s.football_model_version
 or p.code_commit is distinct from s.code_commit or s.code_commit is distinct from current_setting('docked.scanner_commit',true)
 or r.configuration is distinct from s.config->'marketReference' or r.selection is distinct from p_selection
 or not exists(select 1 from beta_private.markets m where m.id=r.market_id and m.event_id=p.event_id and m.rules->>'market'='football_1x2')
 or r.observed_at<p.created_at or checked-p.input_cutoff>(s.config->>'maxSportDataAgeSeconds')::integer*interval '1 second'
 or e.start_at<=checked+greatest(600,(s.config->>'safetySeconds')::integer)*interval '1 second'
 or not coalesce(policy.approved and not policy.preview_community_only and policy.effective_from<=checked and least(policy.effective_to,policy.review_at)>checked and(case when p_purpose='research' then 'market_data' else 'tips' end)=any(policy.features),false)
 then raise exception 'Fresh independent prediction, availability reference and current authority required';end if;
 v:=case when p_selection=e.participants->>0 then(p.probabilities->>'home')::numeric when p_selection='Draw' then(p.probabilities->>'draw')::numeric when p_selection=e.participants->>1 then(p.probabilities->>'away')::numeric else null end;
 if v is null or v<=0 or v>=1 then raise exception 'Selected boundary probability is not an eligible price comparison';end if;
 if r.decimal_price<ceil((1+(s.config->>'minEV')::numeric)/v*100)/100 or r.decimal_price<(s.config->>'minOdds')::numeric or r.decimal_price>(s.config->>'maxOdds')::numeric or v*r.decimal_price-1>(s.config->>'maxEV')::numeric then raise exception 'Independent probability comparison no longer qualifies';end if;
 return v;
end $function$

CREATE OR REPLACE FUNCTION beta_private.assert_football_prediction(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
