  on conflict(request_id,service) do nothing;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION beta_private.preview_fixture_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid; snapshot beta_private.preview_market_sessions; checked_at timestamptz; source jsonb;
begin
 select p.user_id into actor from beta_private.social_profiles p where p.id=new.profile_id and p.status='active' for share;
 if actor is null or actor is distinct from auth.uid() then raise exception 'Preview fixture owner required'; end if;
 if tg_table_name='preview_fixture_edges' then
  select * into snapshot from beta_private.preview_market_sessions where id=new.session_id and profile_id=new.profile_id for update;
  if not found or new.payload_hash is distinct from snapshot.payload_hash then raise exception 'Preview review mismatch'; end if;
 end if;
 -- Rechecks exact project, expiry/revocation, verified active same-user session
 -- and explicit capability after source/profile locks. No metadata-based grant.
 perform beta_private.assert_preview_tester_capability(actor,'preview_market_fixtures');
 checked_at:=clock_timestamp();
 if tg_table_name='preview_market_sessions' then
  if new.observed_at>checked_at or new.observed_at<checked_at-interval '15 seconds'
   or new.expires_at is distinct from new.observed_at+interval '90 seconds'
   or new.payload->>'evidenceMode' is distinct from 'preview' or new.payload->'fixture' is distinct from 'true'::jsonb
   or new.payload->>'label' is distinct from 'DEMO / PREVIEW PRICE'
   or new.payload->>'fixtureId' is distinct from new.fixture_id or new.payload->>'selection' is distinct from new.selection
   or (new.payload->>'observedAt')::timestamptz is distinct from new.observed_at
   or (new.payload->>'expiresAt')::timestamptz is distinct from new.expires_at
   or (new.payload->>'startAt')::timestamptz is distinct from new.observed_at+interval '2 hours'
   or new.payload#>>'{rules,eventId}' is distinct from 'preview:'||new.id::text
   or new.payload#>>'{reference,evidenceMode}' is distinct from 'preview'
   or new.payload#>'{reference,fixture}' is distinct from 'true'::jsonb
   or new.payload#>>'{reference,label}' is distinct from 'DEMO / PREVIEW PRICE'
   or new.payload#>>'{reference,selection}' is distinct from new.selection
   or jsonb_typeof(new.payload->'sources') is distinct from 'array'
   or jsonb_array_length(new.payload->'sources') is distinct from 4
   or new.payload_hash is distinct from encode(sha256(convert_to(beta_private.reference_canonical_json(new.payload),'UTF8')),'hex')
  then raise exception 'Isolated synthetic preview evidence required'; end if;
  for source in select value from jsonb_array_elements(new.payload->'sources') loop
   if source->>'provenance' is distinct from 'fixture' or source->>'provider' is distinct from 'authored-preview-fixture'
    or source->>'bookmaker' not in ('DEMO-P1','DEMO-P2','DEMO-A1','DEMO-A2')
    or source->>'bookmaker' is null
   then raise exception 'Preview cannot import provider evidence'; end if;
  end loop;
 else
  if snapshot.expires_at<=checked_at or snapshot.observed_at>checked_at then raise exception 'Preview review expired'; end if;
  new.submitted_at:=checked_at;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION beta_private.preview_invitation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and old.redeemed_user_id is not null and new.redeemed_user_id is null
 and old.status in ('redeemed','failed','revoked') and (to_jsonb(new)-'redeemed_user_id')=(to_jsonb(old)-'redeemed_user_id')
 then return new; end if; -- Minimal FK erasure is permitted even after the environment/grant expires.
 if current_setting('docked.hosted_preview_project',true) is distinct from 'bckkllmndoxzpzdqrevb'
 then raise exception 'Exact hosted preview required'; end if;
 if tg_op='DELETE' then raise exception 'Revoke invitations; retain minimal audit'; end if;
 if not exists(select 1 from beta_private.region_policies p where p.id=new.policy_id and p.preview_community_only
   and p.country='XX' and p.state='DOCKED_PREVIEW' and p.minimum_age=18 and cardinality(p.operators)=0)
 then raise exception 'Isolated preview policy required'; end if;
 if tg_op='INSERT' and (new.status<>'pending' or new.reservation_id is not null or new.reserved_user_id is not null or new.redeemed_user_id is not null)
 then raise exception 'New invitation must be unused'; end if;
 if tg_op='UPDATE' then
  if (to_jsonb(new)-array['token_hash','email_hash','status','reservation_id','reserved_user_id','redeemed_user_id','changed_at']) is distinct from
     (to_jsonb(old)-array['token_hash','email_hash','status','reservation_id','reserved_user_id','redeemed_user_id','changed_at'])
  then raise exception 'Invitation authority is immutable'; end if;
  if not ((old.status='pending' and new.status in ('reserved','revoked')) or
    (old.status='reserved' and new.status in ('redeemed','failed','revoked')) or
    (old.status in ('redeemed','failed','revoked') and new.status=old.status and new.redeemed_user_id is null and old.redeemed_user_id is not null))
  then raise exception 'Invalid invitation lifecycle'; end if;
  if old.status<>'pending' and (new.reservation_id is distinct from old.reservation_id or new.reserved_user_id is distinct from old.reserved_user_id)
  then raise exception 'Reservation immutable'; end if;
  if old.status='pending' and new.status='reserved' and (old.token_hash is distinct from new.token_hash or old.email_hash is distinct from new.email_hash)
  then raise exception 'Reservation binding immutable'; end if;
  if new.status in ('reserved','redeemed') and (new.expires_at<=clock_timestamp() or not exists(select 1 from beta_private.region_policies p where p.id=new.policy_id and p.approved and p.effective_from<=clock_timestamp() and p.effective_to>clock_timestamp() and p.review_at>clock_timestamp()))
  then raise exception 'Invitation expired or restricted'; end if;
  if new.status='reserved' and new.redeemed_user_id is not null then raise exception 'Premature redemption'; end if;
  if new.status='redeemed' and (new.redeemed_user_id is null or new.redeemed_user_id is distinct from new.reserved_user_id)
  then raise exception 'Redemption must match reserved identity'; end if;
 end if;
 if new.status in ('redeemed','revoked','failed') then new.token_hash=null;new.email_hash=null; end if;
 new.changed_at=clock_timestamp();
 insert into beta_private.audit_events(actor,action,subject,details) values(coalesce(nullif(current_setting('docked.preview_actor',true),''),new.created_by),
  'preview_invitation_'||new.status,new.id::text,jsonb_build_object('projectRef',new.project_ref,'capabilities',new.capabilities,'expiresAt',new.expires_at));
 return new;
end $function$

