CREATE OR REPLACE FUNCTION beta_private.reserve_provider_trial_before_driver_review(p_permit uuid, p_token_hash text, p_scope text, p_cost integer, p_poll uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
