CREATE OR REPLACE FUNCTION beta_private.scanner_schedule_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid;
begin
 if tg_op='DELETE' then raise exception 'Disable scanner schedules; retain history'; end if;
