CREATE OR REPLACE FUNCTION beta_private.social_collection_cards(target uuid, cards jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 declare viewer uuid; owner_profile uuid; prefs beta_private.social_collection_settings;
 begin
   if auth.uid() is null then return '[]'; end if;
   if not beta_private.active_member_session() then raise exception 'Active authenticated session required'; end if; if target=auth.uid() then return cards; end if;
   if not beta_private.community_feature_allowed(auth.uid(),'public_profiles') then return '[]'; end if;
   select id into viewer from beta_private.social_profiles where user_id=auth.uid() and status in ('active','restricted');
   if viewer is null then return '[]'; end if;
   select id into owner_profile from beta_private.social_profiles where user_id=target;
   select * into prefs from beta_private.social_collection_settings where profile_id=owner_profile;
   if not coalesce(beta_private.social_profile_visible(viewer,owner_profile,true) and
     (prefs.visibility='members' or (prefs.visibility='followers' and exists(select 1 from beta_private.social_follows where actor_id=viewer and target_id=owner_profile))),false) then return '[]'; end if;
   return coalesce((select jsonb_agg(c) from jsonb_array_elements(cards) c
     where coalesce(prefs.card_preferences->(c->>'id')->>'hidden','false')<>'true'),'[]');
 end $function$

