AS $function$
        declare viewer uuid; owner_profile uuid; prefs beta_private.social_collection_settings; result jsonb;
        begin
          viewer := beta_private.community_actor(auth.uid(),'public_profiles',false);
          select id into owner_profile from beta_private.social_profiles where user_id=target;
          select * into prefs from beta_private.social_collection_settings where profile_id=owner_profile;
          if target<>auth.uid() and not coalesce((beta_private.social_profile_visible(viewer,owner_profile,true) and
            (prefs.visibility='members' or (prefs.visibility='followers' and exists(select 1 from beta_private.social_follows where actor_id=viewer and target_id=owner_profile)))),false) then return '[]'; end if;
          select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'edition_id',e.id,'player_id',p.id,'serial',c.serial,'name',p.name,'position',p.position,'tier',e.tier,'season',e.season,'kind',e.kind,'max_supply',e.max_supply,'team',p.team,'edition_team',p.team,'colour',p.colour,'shirt',p.shirt,'verifiedJerseyNumber',(select j.verified_jersey_number from sports_feed.nfl_players np join credits_sandbox.permanent_players cp on cp.provider='nflverse' and cp.provider_id=np.provider_id join credits_sandbox.current_player_jerseys j on j.id=cp.id and j.team=np.current_team where np.player_id=p.id limit 1),'status',p.status,'sport',p.sport,'tradeable',c.tradeable)),'[]') into result
          from beta_fantasy.cards c join beta_fantasy.editions e on e.id=c.edition_id join beta_fantasy.players p on p.id=e.player_id where c.owner_id=target;
