CREATE OR REPLACE FUNCTION beta_private.support_privacy_redact(p_case uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c beta_private.privacy_cases; receipt jsonb;
begin
 perform beta_private.require_privacy_owner();
 select * into c from beta_private.privacy_cases where id=p_case for update;
 if not found then raise exception 'Verified support case required';end if;
 if c.state='local_redacted' then return jsonb_build_object('state','local_redacted','retry',true);end if;
 -- Existing erasure trigger removes social text, media bytes, handle history,
 -- follows, notifications and the account-to-social-profile link atomically.
 update beta_public.profiles set disabled_at=clock_timestamp() where id=c.user_id and disabled_at is null;
 update beta_private.admissions set status='suspended' where user_id=c.user_id and status in('reserved','accepted');
 update beta_private.friends_roster set enabled=false where user_id=c.user_id and enabled;
 update beta_fantasy.members set revoked_at=clock_timestamp() where user_id=c.user_id and revoked_at is null;
 delete from beta_public.profiles where id=c.user_id;
 delete from beta_private.analytics_events where user_id=c.user_id;
 update beta_private.outbox set state='suppressed',user_id=null,payload='{}',dedupe_key='erased:'||id::text,last_error='Privacy request',lease_token=null,lease_until=null where user_id=c.user_id;
 receipt:=jsonb_build_object('state','local_redacted','socialTextAndMediaRemoved',true,'betaAccessRevoked',true,
 'auditHistoryPreserved',true,'fullyAnonymous',false,'remainingTasks',jsonb_build_array(
 'Shared Auth identity and residual UUID link require verified cross-product review',
 'Shared Auth identity scope check and revocation/erasure',
 'Microsoft correspondence and provider logs/backups',
 'Review personal references in third-party text and audit reasons'));
 update beta_private.privacy_cases set state='local_redacted',redacted_at=clock_timestamp() where id=p_case;
 perform set_config('docked.privacy_case',p_case::text,true);
 update beta_private.friends_roster set email=replace(c.user_id::text,'-','')||'@deleted.invalid',enabled=false where user_id=c.user_id;
 update beta_private.admissions set email=replace(c.user_id::text,'-','')||'@deleted.invalid',user_id=null where user_id=c.user_id;
 perform set_config('docked.privacy_case','',true);
 insert into beta_private.privacy_events(case_id,action,actor,evidence) values(p_case,'local-redaction',auth.uid(),receipt);
 return receipt;
end$function$

CREATE OR REPLACE FUNCTION beta_private.transition_football_model(p_id text, p_to text, p_reason text, p_evidence jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare actor uuid;s beta_private.football_model_versions;valid boolean;
begin
 actor:=beta_private.scanner_assert_actor(true);select * into s from beta_private.football_model_versions where id=p_id for update;
 if s.id is null or length(btrim(p_reason))<12 then raise exception 'Model and review reason required';end if;
 valid:=(s.lifecycle='DRAFT' and p_to='RESEARCH') or(s.lifecycle='RESEARCH' and p_to='FORWARD_CALIBRATION')
 or(s.lifecycle='FORWARD_CALIBRATION' and p_to='APPROVED_FOR_CANDIDATES') or(s.lifecycle='APPROVED_FOR_CANDIDATES' and p_to='APPROVED_FOR_LIVE')
 or(s.lifecycle<>'RETIRED' and p_to='RETIRED');
 if not valid then raise exception 'Invalid model lifecycle transition';end if;
 if p_to in('APPROVED_FOR_CANDIDATES','APPROVED_FOR_LIVE') and (
 not exists(select 1 from beta_private.football_model_implementations i where i.model_version=s.id and i.code_commit=s.code_commit and i.config_hash=s.config_hash)
 or not exists(select 1 from beta_private.football_model_attempts p join lateral(select result from beta_private.football_model_outcomes where prediction_id=p.id order by sequence desc limit 1)o on true where p.model_version=s.id and p.status='READY' and o.result in('home','draw','away'))
 or not coalesce(p_evidence @> '{"probabilitySanity":true,"dataQuality":true,"operationalReadiness":true,"prospectiveCalibrationReviewed":true}'::jsonb,false)
 ) then raise exception 'Current implementation, prospective calibration and explicit quality review required';end if;
 perform beta_private.scanner_assert_actor(true);
 perform set_config('docked.model_transition',p_id,true);
 update beta_private.football_model_versions set lifecycle=p_to,changed_at=clock_timestamp() where id=p_id;
 perform set_config('docked.model_transition','',true);
 insert into beta_private.football_model_transitions(model_version,from_state,to_state,actor,reason,config_hash,code_commit,configuration,evidence)
 values(p_id,s.lifecycle,p_to,actor,p_reason,s.config_hash,s.code_commit,s.configuration,p_evidence);
 return p_to;
end $function$

CREATE OR REPLACE FUNCTION beta_private.transition_strategy(p_id text, p_to text, p_actor uuid, p_reason text, p_commit text, p_run uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s beta_private.strategy_versions; v beta_private.validation_runs; valid boolean;
begin
 if not exists(select 1 from beta_private.roles where user_id=p_actor and role in ('owner','admin')) then raise exception 'Administrator role required'; end if;
 if length(p_reason)<12 or p_commit!~'^[0-9a-f]{40}$' then raise exception 'Reason and exact code commit required'; end if;
 select * into s from beta_private.strategy_versions where id=p_id for update;
 if not found then raise exception 'Strategy missing'; end if;
 valid=(s.lifecycle='DRAFT' and p_to='RESEARCH') or (s.lifecycle='RESEARCH' and p_to='VALIDATED')
 or (s.lifecycle='VALIDATED' and p_to='FROZEN_FOR_FORWARD_PAPER') or (s.lifecycle='FROZEN_FOR_FORWARD_PAPER' and p_to='FORWARD_PAPER')
 or (s.lifecycle='FORWARD_PAPER' and p_to='APPROVED_FOR_LIVE') or (s.lifecycle<>'RETIRED' and p_to='RETIRED');
 if not valid then raise exception 'Invalid strategy lifecycle transition'; end if;
 if s.frozen_at is not null and s.code_commit is distinct from p_commit then raise exception 'Frozen code commit mismatch'; end if;
 if p_to='FROZEN_FOR_FORWARD_PAPER' and not coalesce(
  (s.config->>'minEV')::numeric>=0.03 and (s.config->>'minEV')::numeric<=0.20
  and (s.config->>'minOdds')::numeric>=1.5 and (s.config->>'maxOdds')::numeric<=5
  and (s.config->>'minOdds')::numeric<=(s.config->>'maxOdds')::numeric,false)
 then raise exception 'Forward paper requires the 3%% EV release floor and odds within 1.5 to 5; research sensitivity settings cannot be frozen for release'; end if;
 if p_to in ('VALIDATED','APPROVED_FOR_LIVE') then
  select * into v from beta_private.validation_runs where id=p_run and strategy_id=p_id;
  if not found or v.contaminated or v.report='{}'::jsonb or v.code_commit<>p_commit
   or v.manifest->>'configHash' is distinct from s.config_hash or coalesce((v.manifest->>'fixture')::boolean,true)
   or not coalesce((v.report->'validation'->>'valid')::boolean,false)
   or (p_to='VALIDATED' and (v.manifest->'datasetHashes'->>'canonical') is null)
   or (p_to='APPROVED_FOR_LIVE' and not exists(select 1 from beta_private.tip_publications where strategy_id=p_id and evidence='forward_paper'))
   or (p_to='VALIDATED' and v.evidence<>'retrospective_backtest') or (p_to='APPROVED_FOR_LIVE' and v.evidence<>'forward_paper')
  then raise exception 'Matching uncontaminated genuine validation report required'; end if;
 end if;
 perform set_config('docked.strategy_transition',p_id,true);
 update beta_private.strategy_versions set lifecycle=p_to,state_changed_at=clock_timestamp(),code_commit=p_commit,
 frozen_at=case when p_to='FROZEN_FOR_FORWARD_PAPER' then coalesce(frozen_at,clock_timestamp()) else frozen_at end,
 active=p_to in ('FORWARD_PAPER','APPROVED_FOR_LIVE'),
 research_approved_at=case when p_to='VALIDATED' then clock_timestamp() else research_approved_at end,
 paper_approved_at=case when p_to='APPROVED_FOR_LIVE' then clock_timestamp() else paper_approved_at end,
 owner_approved_at=case when p_to='APPROVED_FOR_LIVE' then clock_timestamp() else owner_approved_at end,
 approval_evidence=p_reason where id=p_id;
 insert into beta_private.strategy_transitions(strategy_id,from_state,to_state,actor,strategy_hash,code_commit,reason,validation_run_id,configuration)
 values(p_id,s.lifecycle,p_to,p_actor,s.config_hash,p_commit,p_reason,p_run,s.config);
 perform set_config('docked.strategy_transition','',true);
 return p_to;
end $function$

CREATE OR REPLACE FUNCTION beta_private.two_person_admission_guard_before_friends()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$declare c beta_private.two_person_control;begin
 select * into c from beta_private.two_person_control where id for share;
 if not found then return new;end if;
 if new.administrator then
 if new.user_id is distinct from c.owner_id then raise exception 'Only the existing owner is exempt';end if;
 else
 if new.user_id is distinct from c.tester_id or (not c.tester_enabled and new.status not in('revoked','suspended')) then raise exception 'Only the designated tester may be invited';end if;
 if tg_op='INSERT' and exists(select 1 from beta_private.admissions where not administrator) then raise exception 'One tester lifetime admission limit';end if;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION beta_private.two_person_control_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='DELETE' then raise exception 'Two-person boundary is permanent'; end if;
 if tg_op='UPDATE' and (new.owner_id<>old.owner_id or (old.tester_id is not null and new.tester_id is distinct from old.tester_id)) then raise exception 'Beta participant identities are permanent';end if;
 if not exists(select 1 from beta_private.owner_gameplay_control where owner_id=new.owner_id) then raise exception 'Existing owner required';end if;
 if new.tester_id is not null and (exists(select 1 from beta_private.roles where user_id=new.tester_id) or exists(select 1 from beta_private.designated_administrators where user_id=new.tester_id)) then raise exception 'Tester must be an ordinary member';end if;
 if exists(select 1 from beta_private.admissions where not administrator and user_id is distinct from new.tester_id) then raise exception 'Unexpected existing tester admission';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION commercial_billing.append_lineup(s jsonb, sport_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cards jsonb;extra jsonb;u uuid;rounds jsonb;begin
 u:=(s->>'user_id')::uuid;rounds:=coalesce(s->'competitions','[]');
 if not exists(select 1 from jsonb_array_elements(rounds) c where c->'rules'->>'commercial_inventory_policy'='commercial-owned-v1') then return s;end if;
 cards:=case when sport_id='nfl' then coalesce(s#>'{seven,inventory}','[]') else coalesce(s->'cards','[]') end;
 select coalesce(jsonb_agg(card || jsonb_build_object('eligible_competition_ids',coalesce((
  select jsonb_agg(c->>'id') from jsonb_array_elements(rounds)c
  where c->'rules'->>'commercial_inventory_policy' is distinct from 'commercial-owned-v1'
   and (not card ? 'eligible_competition_ids' or card->'eligible_competition_ids' ? (c->>'id'))
 ),'[]'))),'[]') into cards from jsonb_array_elements(cards)card;
 select coalesce(jsonb_agg(card || jsonb_build_object('eligible_competition_ids',ids)),'[]') into extra from (
  select v-'eligible_competition_ids' card,jsonb_agg(distinct c->>'id') ids from jsonb_array_elements(rounds)c
  cross join lateral jsonb_array_elements(commercial_billing.lineup_inventory(u,(c->>'id')::uuid))v
  where c->>'sport'=sport_id group by v-'eligible_competition_ids'
 )q;
 -- A free Core ID can be eligible in both programme types; merge by stable ID.
 select coalesce(jsonb_agg(card || jsonb_build_object('eligible_competition_ids',ids)),'[]') into cards from (
  select v-'eligible_competition_ids' card,jsonb_agg(distinct id) ids from jsonb_array_elements(cards||extra)v
  cross join lateral jsonb_array_elements(v->'eligible_competition_ids')id group by v-'eligible_competition_ids'
 )q;
 if sport_id='nfl' then return jsonb_set(s,'{seven,inventory}',cards);end if;
 return jsonb_set(s,'{cards}',cards);
end$function$

CREATE OR REPLACE FUNCTION commercial_billing.card_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare d commercial_billing.definitions;
begin
 if tg_op='UPDATE' then
  if (to_jsonb(new)-array['owner_id','locked'])<>(to_jsonb(old)-array['owner_id','locked']) then raise exception 'Permanent card identity immutable'; end if;
 else
  select * into strict d from commercial_billing.definitions where id=new.definition for update;
  if not d.approved or new.serial<>d.issued+1 or new.serial>d.lifetime_cap then raise exception 'Supply exhausted or definition not approved'; end if;
  update commercial_billing.definitions set issued=new.serial where id=d.id;
 end if; return new;
end$function$

CREATE OR REPLACE FUNCTION commercial_billing.check_journal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (select coalesce(sum(amount),0) from commercial_billing.lines where journal=new.journal)<>0 then raise exception 'Unbalanced commercial journal'; end if;
 if exists(select 1 from commercial_billing.lines l join commercial_billing.journals j on j.id=l.journal where j.unit='CREDITS' and l.account=new.account and l.account like 'member:%' group by l.account having sum(l.amount)<0) then raise exception 'Negative commercial credit balance'; end if;
 return null;
end$function$

CREATE OR REPLACE FUNCTION commercial_billing.lineup_transfer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare card_id uuid;begin
 perform pg_advisory_xact_lock(71820342);
 if tg_table_name='listings' then card_id:=new.card;
 elsif new.owner_id is distinct from old.owner_id then card_id:=old.id;end if;
 if card_id is not null and sports_feed.card_entry_reserved(card_id) then raise exception 'Card reserved by submitted lineup';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION commercial_billing.lot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (new.id,new.member_id,new.receipt,new.source,new.original,new.created_at) is distinct from (old.id,old.member_id,old.receipt,old.source,old.original,old.created_at)
 or new.remaining>old.remaining or new.refund_removed<old.refund_removed then raise exception 'Credit provenance immutable'; end if;
