CREATE OR REPLACE FUNCTION sports_feed.seven_admin_control(p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;c uuid;old beta_fantasy.round_controls;answer jsonb;prior beta_fantasy.requests;begin
 perform pg_advisory_xact_lock(71820342);u:=beta_fantasy.production_eligible();
 if not beta_private.active_member_session() or auth.jwt()->>'aal' is distinct from 'aal2' or not exists(select 1 from beta_private.roles where user_id=u and role in('owner','admin')) then raise exception 'Owner/admin MFA required';end if;
 if request_id is null or (select count(*) from jsonb_object_keys(p))<>5 or not p ?& array['competition_id','revision','enabled','standings_visible','reason'] or jsonb_typeof(p->'enabled')<>'boolean' or jsonb_typeof(p->'standings_visible')<>'boolean' or length(trim(p->>'reason'))<12 then raise exception 'Explicit controls and reason required';end if;
 select * into prior from beta_fantasy.requests r where user_id=u and r.request_id=seven_admin_control.request_id;
 if found then if prior.action<>'seven_admin_control' or prior.payload<>p then raise exception 'Request ID reused';end if;return prior.result;end if;
 c:=(p->>'competition_id')::uuid;
 if not exists(select 1 from beta_fantasy.competitions where id=c and rules->>'lineup_version' is not null) then raise exception 'Seven-slot round required';end if;
 select * into old from beta_fantasy.round_controls where competition_id=c for update;
 if coalesce(old.revision,0)<>(p->>'revision')::int then raise exception 'Controls changed; refresh';end if;
 insert into beta_fantasy.round_controls values(c,(p->>'enabled')::boolean,(p->>'standings_visible')::boolean,coalesce(old.revision,0)+1) on conflict(competition_id) do update set enabled=excluded.enabled,standings_visible=excluded.standings_visible,revision=excluded.revision;
 answer:=jsonb_build_object('updated',true,'revision',coalesce(old.revision,0)+1);
 insert into beta_private.audit_events(actor,action,subject,details) values(u::text,'seven_round_control',c::text,jsonb_build_object('previous',to_jsonb(old),'result',p,'request',request_id));
 insert into beta_fantasy.requests values(u,request_id,'seven_admin_control',p,answer);return answer;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.seven_command(action text, p jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;c beta_fantasy.competitions;cfg jsonb;inv jsonb;item jsonb;card jsonb;slot jsonb;locked jsonb;f jsonb;
 prior beta_fantasy.requests;e beta_fantasy.entries;d beta_fantasy.round_drafts;
 snap jsonb:='[]';ids uuid[]:='{}';players text[]:='{}';slots text[]:='{}';total bigint:=0;rev integer;answer jsonb;now_at timestamptz;
begin
 perform pg_advisory_xact_lock(71820342);
 u:=sports_feed.lineup_actor();
 if not sports_feed.lineup_actor_allowed(u) then raise exception 'Invited test member required';end if;
 perform 1 from credits_sandbox.state where id for update;
 perform sports_feed.seven_lock_due();now_at:=clock_timestamp();
 if action not in('seven_draft','seven_enter','seven_withdraw') or request_id is null or jsonb_typeof(p)<>'object' then raise exception 'Invalid lineup command';end if;
 select * into prior from beta_fantasy.requests q where q.user_id=u and q.request_id=seven_command.request_id;
 if found then if prior.action<>action or prior.payload<>p then raise exception 'Request ID reused';end if;return prior.result;end if;
 if (select count(*) from jsonb_object_keys(p))<>3 or not p ?& array['competition_id','revision','selections'] or jsonb_typeof(p->'selections')<>'array' or (p->>'revision')!~'^[0-9]+$' then raise exception 'Exact versioned selection payload required';end if;
 select * into strict c from beta_fantasy.competitions where id=(p->>'competition_id')::uuid;
 select configuration into cfg from beta_fantasy.lineup_configurations where version=c.rules->>'lineup_version';
 if cfg is null or c.rules->>'mode' not in('SALARY_CAP','OPEN') or sports_feed.lineup_scope_allowed(c.id) is distinct from true or c.scored_at is not null or (c.opens_at>now_at and action<>'seven_draft') or exists(select 1 from beta_fantasy.round_controls where competition_id=c.id and not enabled) then raise exception 'Competition unavailable';end if;
 select * into e from beta_fantasy.entries where competition_id=c.id and user_id=u for update;
 select * into d from beta_fantasy.round_drafts where competition_id=c.id and user_id=u for update;
 if (action='seven_draft' and coalesce(d.revision,0)<>(p->>'revision')::int) or (action<>'seven_draft' and coalesce(e.lineup_revision,0)<>(p->>'revision')::int) then raise exception 'Team changed in another window. Refresh before saving';end if;
 if c.locks_at<=now_at and (c.rules->>'lock_policy'='round-wide-v1' or e.id is null or action='seven_withdraw') then raise exception 'New entries and withdrawals closed at first kickoff';end if;
 if action='seven_withdraw' then
 if p->'selections'<>'[]' then raise exception 'Empty withdrawal selections required';end if;
 select coalesce(max(revision),0)+1 into rev from beta_fantasy.entry_revisions where competition_id=c.id and user_id=u;
 insert into beta_fantasy.entry_revisions(competition_id,user_id,revision,action,snapshot,actor) values(c.id,u,rev,action,coalesce(e.snapshot,'[]'),u);
 delete from beta_fantasy.entries where competition_id=c.id and user_id=u;
 answer:=jsonb_build_object('withdrawn',true,'competition_id',c.id);
 else
 if jsonb_array_length(p->'selections')>jsonb_array_length(cfg->'slots') or (action='seven_enter' and jsonb_array_length(p->'selections')<>jsonb_array_length(cfg->'slots')) then if c.sport='nfl' then raise exception 'Entry requires exactly seven slots; draft may be incomplete'; else raise exception 'Entry must fill every configured slot; draft may be incomplete';end if;end if;
 inv:=sports_feed.lineup_inventory(u,c.id);
 for item in select value from jsonb_array_elements(p->'selections') loop
 if (select count(*) from jsonb_object_keys(item))<>2 or not item ?& array['slot','card'] then raise exception 'Only slot and card ID accepted';end if;
 select value into slot from jsonb_array_elements(cfg->'slots') where value->>'id'=item->>'slot';
 if slot is null or item->>'slot'=any(slots) then raise exception 'Invalid or repeated slot';end if;
 select snapshot into locked from beta_fantasy.slot_locks where competition_id=c.id and user_id=u and beta_fantasy.slot_locks.slot=item->>'slot';
 if locked is not null then
 if locked->>'card_id'<>item->>'card' then raise exception 'Started player cannot be replaced or moved';end if;card:=locked;
 else
 select value into card from jsonb_array_elements(inv) where value->>'id'=item->>'card';
 if card is null or card->>'status'<>'active' or (card->>'listed')::boolean or not sports_feed.lineup_position_eligible(card,slot) or (c.sport<>'nfl' and (card->>'sport' is distinct from c.sport or card->>'owner_id' is distinct from u::text)) then raise exception 'Owned, opened, unlisted eligible card required for this position';end if;
 f:=sports_feed.lineup_player_fixture(c.id,card->>'player_id');if f is null then raise exception 'Reliable unique fixture mapping required';end if;

 if f->>'scheduledAt' is null or coalesce(f->>'status','scheduled')<>'scheduled' then raise exception 'Fixture time unavailable or schedule under review';end if;
 if (f->>'scheduledAt')::timestamptz<=now_at then raise exception 'A player whose game started cannot be added';end if;
 card:=card||jsonb_build_object('card_id',card->>'id','slot',item->>'slot','kickoff',f->>'scheduledAt','fixture_id',f->>'fixtureId','salary',cfg->'salaries'->(card->>'tier'),'lineup_version',cfg->>'version','rules_version',c.rules->>'scoring_version');if c.sport<>'nfl' then card:=card||jsonb_build_object('fixture_ids',coalesce(f->'fixture_ids',jsonb_build_array(f->>'fixtureId')));end if;
 end if;
 if (case when c.sport='basketball' and c.rules->>'lineup_version'='docked-nba-weekly-lineup-proposal-v1' then coalesce(card->>'canonical_player_id',card->>'player_id') else card->>'player_id' end)=any(players) then raise exception 'Only one card of each underlying player';end if;
 if card->>'salary' is null or card->>'multiplierTenths' is null then raise exception 'Authoritative card configuration unavailable';end if;
 total:=total+(card->>'salary')::bigint;snap:=snap||jsonb_build_array(card);ids:=array_append(ids,(card->>'card_id')::uuid);players:=array_append(players,(case when c.sport='basketball' and c.rules->>'lineup_version'='docked-nba-weekly-lineup-proposal-v1' then coalesce(card->>'canonical_player_id',card->>'player_id') else card->>'player_id' end));slots:=array_append(slots,item->>'slot');
 end loop;
 if exists(select 1 from beta_fantasy.slot_locks where competition_id=c.id and user_id=u and not(beta_fantasy.slot_locks.slot=any(slots))) then raise exception 'Locked slots must remain in their original position';end if;
 if c.rules->>'mode'='SALARY_CAP' and total>(cfg->>'salaryCap')::bigint then raise exception 'Salary cap exceeded: attempted %, cap %',total,cfg->>'salaryCap';end if;
 if action='seven_draft' then
 rev:=coalesce(d.revision,0)+1;
 insert into beta_fantasy.round_drafts values(c.id,u,rev,p->'selections',now_at) on conflict(competition_id,user_id) do update set revision=excluded.revision,selections=excluded.selections,updated_at=excluded.updated_at;
 else
 select coalesce(max(revision),0)+1 into rev from beta_fantasy.entry_revisions where competition_id=c.id and user_id=u;
 insert into beta_fantasy.entries(competition_id,user_id,cards,snapshot,lineup_revision) values(c.id,u,ids,snap,rev) on conflict(competition_id,user_id) do update set cards=excluded.cards,snapshot=excluded.snapshot,lineup_revision=excluded.lineup_revision,updated_at=now_at;
 insert into beta_fantasy.entry_revisions(competition_id,user_id,revision,action,snapshot,actor) values(c.id,u,rev,action,snap,u);
 insert into sports_feed.stream_members(stream_id,user_id) select stream_id,u from sports_feed.nfl_rounds where competition_id=c.id on conflict do nothing;
 end if;
 answer:=jsonb_build_object('saved',true,'entered',action='seven_enter','revision',rev,'salary',total,'competition_id',c.id);
 end if;
 insert into beta_fantasy.requests values(u,request_id,action,p,answer);
 insert into beta_private.audit_events(actor,action,subject,details) values(u::text,action,c.id::text,jsonb_build_object('revision',rev,'request',request_id,'previous',case when action='seven_draft' then d.selections else e.snapshot end,'result',answer));
 return answer;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.seven_continue_teams()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid; target beta_fantasy.competitions; source_id uuid; source_picks jsonb;
 cfg jsonb; inv jsonb; item jsonb; card jsonb; slot jsonb; fixture jsonb;
 picks jsonb; omitted jsonb; reason text; players text[]; slots text[]; total bigint;
 context jsonb; now_at timestamptz:=clock_timestamp();
begin
 u:=sports_feed.lineup_actor();
 if not sports_feed.lineup_actor_allowed(u) then raise exception 'Invited test member required'; end if;
 -- Immutable entry revisions keep first setup confirmed even after withdrawal.
 select coalesce(jsonb_object_agg(chain,true),'{}') into context from (
  select distinct c.sport||':'||(c.rules->>'mode') chain
  from beta_fantasy.entry_revisions r join beta_fantasy.competitions c on c.id=r.competition_id
  where r.user_id=u and r.action='seven_enter' and c.rules->>'lineup_version' is not null
 ) established;
 for target in
  select c.* from beta_fantasy.competitions c
  left join beta_fantasy.production_rounds pr on pr.competition_id=c.id
  left join sports_feed.nfl_rounds nr on nr.competition_id=c.id
  where c.rules->>'lineup_version' is not null
   and c.rules->>'mode' in ('SALARY_CAP','OPEN') and sports_feed.lineup_scope_allowed(c.id)
   and ((c.sport='nfl' and (pr.release_channel=beta_fantasy.production_channel() or (c.sport<>'nfl' and sports_feed.lineup_scope_allowed(c.id))) and nr.purpose='member') or (c.sport<>'nfl' and sports_feed.lineup_scope_allowed(c.id)))
   and c.scored_at is null and c.locks_at>now_at
   and not exists(select 1 from beta_fantasy.round_controls where competition_id=c.id and not enabled)
   and not exists(select 1 from beta_fantasy.round_drafts where competition_id=c.id and user_id=u)
   and not exists(select 1 from beta_fantasy.entries where competition_id=c.id and user_id=u)
   and not exists(select 1 from beta_fantasy.team_rollovers where competition_id=c.id and user_id=u)
  order by c.season,c.round,c.id
 loop
  perform pg_advisory_xact_lock(71820342);
  if exists(select 1 from beta_fantasy.round_drafts where competition_id=target.id and user_id=u)
   or exists(select 1 from beta_fantasy.entries where competition_id=target.id and user_id=u)
   or exists(select 1 from beta_fantasy.team_rollovers where competition_id=target.id and user_id=u) then continue; end if;
  -- Never backfill a week before this chain's first confirmed entry.
  if not exists(select 1 from beta_fantasy.entry_revisions r join beta_fantasy.competitions c on c.id=r.competition_id
   where r.user_id=u and r.action='seven_enter' and c.sport=target.sport and c.rules->>'mode'=target.rules->>'mode'
   and c.rules->>'inventory_scope'=target.rules->>'inventory_scope' and (c.season,c.round)<(target.season,target.round)) then continue; end if;
  select c.id,case when e.id is not null then (select jsonb_agg(jsonb_build_object('slot',s->>'slot','card',s->>'card_id')) from jsonb_array_elements(e.snapshot)s) else d.selections end
   into source_id,source_picks
   from beta_fantasy.competitions c left join beta_fantasy.production_rounds pr on pr.competition_id=c.id
   left join beta_fantasy.entries e on e.competition_id=c.id and e.user_id=u
   left join beta_fantasy.round_drafts d on d.competition_id=c.id and d.user_id=u
   where c.sport=target.sport and c.rules->>'mode'=target.rules->>'mode'
    and c.rules->>'inventory_scope'=target.rules->>'inventory_scope'
    and (pr.release_channel=beta_fantasy.production_channel() or (c.sport<>'nfl' and sports_feed.lineup_scope_allowed(c.id)))
    and (c.season,c.round)<(target.season,target.round) and (e.id is not null or d.competition_id is not null)
   order by c.season desc,c.round desc limit 1;
  if source_id is null then continue; end if;
  select configuration into cfg from beta_fantasy.lineup_configurations where version=target.rules->>'lineup_version';
  if cfg is null then continue; end if;
  inv:=sports_feed.lineup_inventory(u,target.id);
  picks:='[]';omitted:='[]';players:='{}';slots:='{}';total:=0;
  -- Keep original slot order/card instances; never optimise or substitute.
  for item in select value from jsonb_array_elements(coalesce(source_picks,'[]')) loop
   reason:=null;fixture:=null;
   select value into slot from jsonb_array_elements(cfg->'slots') where value->>'id'=item->>'slot';
   select value into card from jsonb_array_elements(inv) where value->>'id'=item->>'card';
   if slot is null or item->>'slot'=any(slots) then reason:='Position is not available in this round';
   elsif card is null then reason:='Card is no longer in your eligible collection';
   elsif card->>'status'<>'active' then reason:='Current player eligibility is unavailable';
   elsif coalesce((card->>'listed')::boolean,false) then reason:='Card is listed for sale';
   elsif not sports_feed.lineup_position_eligible(card,slot) then reason:='Player is not eligible for this position';
   elsif card->>'player_id'=any(players) then reason:='Player already selected';
   elsif sports_feed.lineup_player_fixture(target.id,card->>'player_id') is null then reason:='No reliable unique fixture for this week';
   else
    fixture:=sports_feed.lineup_player_fixture(target.id,card->>'player_id');
    if fixture->>'scheduledAt' is null or coalesce(fixture->>'status','scheduled')<>'scheduled' then reason:='Fixture schedule is under review';
    elsif (fixture->>'scheduledAt')::timestamptz<=now_at then reason:='Player game has started';
    elsif cfg->'salaries'->>(card->>'tier') is null or card->>'multiplierTenths' is null then reason:='Card configuration is unavailable';
    elsif target.rules->>'mode'='SALARY_CAP' and total+(cfg->'salaries'->>(card->>'tier'))::bigint>(cfg->>'salaryCap')::bigint then reason:='Review this position to fit the salary cap'; end if;
   end if;
   if reason is null then
    picks:=picks||jsonb_build_array(item);slots:=array_append(slots,item->>'slot');players:=array_append(players,card->>'player_id');total:=total+(cfg->'salaries'->>(card->>'tier'))::bigint;
   else omitted:=omitted||jsonb_build_array(jsonb_build_object('slot',item->>'slot','reason',reason)); end if;
  end loop;
  -- Reuse the authoritative command: eligibility, cap, revision, audit and locks.
  perform sports_feed.seven_command('seven_draft',jsonb_build_object('competition_id',target.id,'revision',0,'selections',picks),gen_random_uuid());
  insert into beta_fantasy.team_rollovers(competition_id,user_id,source_competition_id,selections,omitted) values(target.id,u,source_id,picks,omitted);
 end loop;
 return jsonb_build_object('established',context,'rollovers',coalesce((select jsonb_agg(to_jsonb(r)-'user_id') from beta_fantasy.team_rollovers r where user_id=u),'[]'));
end$function$

CREATE OR REPLACE FUNCTION sports_feed.seven_final_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from beta_fantasy.competitions where id=new.competition_id and rules->>'lineup_version' is not null) and exists(
  select 1 from jsonb_array_elements(new.snapshot) s
  where (s->>'kickoff')::timestamptz<=clock_timestamp() and not exists(
   select 1 from beta_fantasy.slot_locks l where l.competition_id=new.competition_id and l.user_id=new.user_id and l.slot=s->>'slot' and l.snapshot=s
  )
 ) then raise exception 'Kickoff crossed during save. Refresh: newly started players cannot be added';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.sport_sandbox_state_before_parity(sport_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid;continuity jsonb;begin
 u:=sports_feed.sandbox_identity(); if current_setting('docked.nba_private_beta',true)='enabled' and sport_id is distinct from sports_feed.private_beta_sport() then raise exception 'Sport context mismatch';end if;
 if (auth.jwt()->>'aal' is distinct from 'aal2' and coalesce(current_setting('docked.nba_private_beta',true),'')<>'enabled') or current_setting('docked.multi_sport',true) is distinct from 'isolated-preview' or u is null
 or not exists(select 1 from sports_feed.sport_sandbox_access where user_id=u) then raise exception 'Isolated sport access required';end if;
 continuity:=sports_feed.seven_continue_teams();
 perform sports_feed.seven_lock_due();
 return jsonb_build_object('user_id',u,'sport',sport_id,'server_time',clock_timestamp(),'continuity',continuity,
 'cards',case when current_setting('docked.nba_private_beta',true)='enabled' then sports_feed.owned_sport_inventory(u,sport_id) else coalesce((select cards from sports_feed.sport_sandbox_inventory where user_id=u and sport=sport_id),'[]') end,
 'configurations',coalesce((select jsonb_object_agg(version,configuration) from beta_fantasy.lineup_configurations where configuration->>'sport'=sport_id),'{}'),
 'competitions',coalesce((select jsonb_agg(to_jsonb(c)) from beta_fantasy.competitions c join sports_feed.sport_rounds r on r.competition_id=c.id where c.sport=sport_id and sports_feed.lineup_scope_allowed(c.id)),'[]'),
 'drafts',coalesce((select jsonb_agg(to_jsonb(d)-'user_id') from beta_fantasy.round_drafts d join sports_feed.sport_rounds r on r.competition_id=d.competition_id where d.user_id=u and r.sport=sport_id and sports_feed.lineup_scope_allowed(d.competition_id)),'[]'),
 'entries',coalesce((select jsonb_agg(jsonb_build_object('competition_id',e.competition_id,'user_id',e.user_id,'snapshot',e.snapshot,'revision',e.lineup_revision,'updated_at',e.updated_at)) from beta_fantasy.entries e join beta_fantasy.competitions c on c.id=e.competition_id join sports_feed.sport_rounds r on r.competition_id=c.id
 where r.sport=sport_id and sports_feed.lineup_scope_allowed(c.id) and (e.user_id=u or (c.locks_at<=clock_timestamp() and exists(select 1 from beta_fantasy.entries own where own.competition_id=c.id and own.user_id=u)))),'[]'));
end$function$

CREATE OR REPLACE FUNCTION sports_feed.starter_entitlement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='DELETE' then raise exception 'Starter entitlement history is permanent';end if;
 if (to_jsonb(new)-'opened_at') is distinct from (to_jsonb(old)-'opened_at') or old.opened_at is not null or new.opened_at is null then raise exception 'Starter entitlement may only be opened once';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.weekly_core_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='DELETE' then raise exception 'Weekly reward history is permanent';end if;
 if tg_table_name='weekly_core_schedules' then
  if (to_jsonb(new)-'next_period') is distinct from (to_jsonb(old)-'next_period') or new.next_period<old.next_period then raise exception 'Reward anchor is immutable';end if;
 else
  if (to_jsonb(new)-array['opened_at','receipt']) is distinct from (to_jsonb(old)-array['opened_at','receipt']) or old.opened_at is not null or new.opened_at is null then raise exception 'Weekly pack may only open once';end if;
 end if;return new;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.weekly_core_job()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;n int;run uuid;additional int:=0;failure_count int:=0;begin
 n:=sports_feed.weekly_core_nfl_job();
 if not exists(select 1 from sports_feed.weekly_sport_programmes where enabled) then return n;end if;
 insert into sports_feed.weekly_core_job_runs(status) values('running') returning id into run;
 for r in select a.user_id,p.sport from credits_sandbox.access a cross join sports_feed.weekly_sport_programmes p
 left join sports_feed.weekly_core_schedules s on s.user_id=a.user_id and s.sport=p.sport
 where p.enabled and sports_feed.weekly_core_allowed(a.user_id,p.sport) and (s.user_id is null or s.enrolled_at+s.next_period*interval '604800 seconds'<=clock_timestamp())
 order by s.enrolled_at+s.next_period*interval '604800 seconds' nulls first,a.user_id,p.sport limit 100 loop
  begin additional:=additional+sports_feed.weekly_core_reconcile(r.user_id,r.sport);
  exception when others then failure_count:=failure_count+1;insert into sports_feed.weekly_core_job_failures(run_id,user_id,sport,sqlstate) values(run,r.user_id,r.sport,sqlstate);end;
 end loop;
 update sports_feed.weekly_core_job_runs set finished_at=clock_timestamp(),issued=additional,failures=failure_count,status=case when failure_count>0 then 'partial' else 'complete' end where id=run;
 return n+additional;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.weekly_core_nfl_job()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; run uuid; n integer:=0; failure_count integer:=0;begin
 perform pg_advisory_xact_lock(71820342);
 if not exists(select 1 from sports_feed.weekly_core_control where enabled) then return 0;end if;
 insert into sports_feed.weekly_core_job_runs(status) values('running') returning id into run;
 for r in select a.user_id from credits_sandbox.access a left join sports_feed.weekly_core_schedules s on s.user_id=a.user_id and s.sport='nfl'
 where a.enabled and sports_feed.weekly_core_allowed(a.user_id)
 and (s.user_id is null or s.enrolled_at+s.next_period*interval '604800 seconds'<=clock_timestamp())
 order by s.enrolled_at+s.next_period*interval '604800 seconds' nulls first,a.user_id limit 100 loop
  begin n:=n+sports_feed.weekly_core_reconcile(r.user_id);
  exception when others then
   failure_count:=failure_count+1;
   insert into sports_feed.weekly_core_job_failures(run_id,user_id,sqlstate) values(run,r.user_id,sqlstate);
  end;
 end loop;
 update sports_feed.weekly_core_job_runs set finished_at=clock_timestamp(),issued=n,failures=failure_count,status=case when failure_count>0 then 'partial' else 'complete' end where id=run;
 return n;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.weekly_core_reconcile(u uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s sports_feed.weekly_core_schedules; now_at timestamptz; last_period integer; n integer;begin
 perform pg_advisory_xact_lock(71820342);
 if not sports_feed.weekly_core_allowed(u) then return 0;end if;
 now_at:=clock_timestamp();
 insert into sports_feed.weekly_core_schedules(user_id,enrolled_at) values(u,now_at) on conflict do nothing;
 select * into strict s from sports_feed.weekly_core_schedules where user_id=u and sport='nfl' for update;
 -- 604800 seconds, not local-calendar days; bounded catch-up remains due for the next run.
 last_period:=least(floor(extract(epoch from(now_at-s.enrolled_at))/604800)::int,s.next_period+499);
 insert into sports_feed.weekly_core_packs(user_id,period,due_at,issued_at)
 select u,i,s.enrolled_at+i*interval '604800 seconds',now_at from generate_series(s.next_period,last_period)i on conflict(user_id,sport,period) do nothing;
 get diagnostics n=row_count;
 if last_period>=s.next_period then update sports_feed.weekly_core_schedules set next_period=last_period+1 where user_id=u and sport='nfl';end if;
 return n;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.weekly_core_reconcile(u uuid, s text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare schedule sports_feed.weekly_core_schedules;now_at timestamptz:=clock_timestamp();last_period int;n int;begin
 if s='nfl' then return sports_feed.weekly_core_reconcile(u);end if;
 perform pg_advisory_xact_lock(71820342);
 if not sports_feed.weekly_core_allowed(u,s) then return 0;end if;
 -- First eligibility processing anchors the programme. No backdated rewards.
 insert into sports_feed.weekly_core_schedules(user_id,sport,policy,enrolled_at)
 values(u,s,'weekly-core-'||s||'-v1',now_at) on conflict do nothing;
 select * into strict schedule from sports_feed.weekly_core_schedules where user_id=u and sport=s for update;
 last_period:=least(floor(extract(epoch from(now_at-schedule.enrolled_at))/604800)::int,schedule.next_period+499);
 insert into sports_feed.weekly_core_packs(user_id,sport,policy,period,due_at,issued_at)
 select u,s,schedule.policy,i,schedule.enrolled_at+i*interval '604800 seconds',now_at from generate_series(schedule.next_period,last_period)i
 on conflict(user_id,sport,period) do nothing;
 get diagnostics n=row_count;
 if last_period>=schedule.next_period then update sports_feed.weekly_core_schedules set next_period=last_period+1 where user_id=u and sport=s;end if;
 return n;
end$function$

CREATE OR REPLACE FUNCTION sports_feed.weekly_core_setup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare u uuid;begin
 u:=case when tg_table_schema='beta_public' then (to_jsonb(new)->>'id')::uuid else (to_jsonb(new)->>'user_id')::uuid end;
 if u is not null then perform sports_feed.weekly_core_reconcile(u);end if;
 return new;
end$function$
